window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-08-12"]={"date":"2026-08-12","dateKR":"2026년 8월 12일","dateEN":"12 August 2026","total":140,"sections":[{"code":"TOP","type":"news","kTitle":"Section 1. 주요 뉴스","eTitle":"Section 1. Top News","items":[{"code":"TOP","title":"Star Bulk walks away from Genco fleet deal","src":"Splash247","date":"2026-08-11","kSum":"스타벌크(Star Bulk)가 디아나 시핑(Diana Shipping)으로부터 젠코(Genco) 벌커 16척을 4억7,050만 달러에 인수하려던 계약에서 철수했다. 이로써 디아나의 장기 젠코 인수 시도에서 핵심 자산 조각이 빠지게 됐다.","eSum":"Star Bulk Carriers has pulled out of a $470.5m agreement to acquire 16 Genco bulkers from Diana Shipping, removing a key component of Diana's long-running takeover attempt for Genco. The collapse reshapes an active dry bulk consolidation battle.","kImp":"드라이벌크 대형 인수·합병 구도가 흔들리며 선대 재편 향방에 영향.","eImp":"A pivotal move in dry bulk M&A that reshuffles ongoing consolidation dynamics.","url":"https://splash247.com/star-bulk-walks-away-from-genco-fleet-deal/"},{"code":"TOP","title":"CMB.TECH locks in $57m gain on two-year-old suezmax","src":"Splash247","date":"2026-08-11","kSum":"CMB.TECH가 2024년 건조된 15만6,851dwt 수에즈막스 '브리스톨(Bristol)'을 매각해 약 5,690만 달러의 자본이득을 확정했다. 인도는 4분기로 예정돼 있으며, 강세인 원유선 자산 가치를 활용한 거래다.","eSum":"CMB.TECH has sold the 2024-built, 156,851 dwt suezmax Bristol, locking in a capital gain of about $56.9m as it capitalizes on strong crude tanker values. Delivery to the undisclosed buyer is set for Q4.","kImp":"탱커 자산가치 강세 속 선주들의 차익 실현 흐름을 보여주는 사례.","eImp":"Signals continued profit-taking by owners amid red-hot tanker asset values.","url":"https://splash247.com/cmb-tech-locks-in-57m-gain-on-two-year-old-suezmax/"},{"code":"TOP","title":"Pemont adds LR2 newbuilds to Montanari renewal push","src":"Splash247","date":"2026-08-11","kSum":"이탈리아 탱커 선주 나비가치오네 몬타나리(Navigazione Montanari)가 몰타 소재 계열사 페몬트(Pemont)를 통해 중국 헝리중공업(Hengli Heavy Industry)에 LR2 제품운반선 2척을 발주했다. 급성장 중인 다롄 조선소와 새로운 협력관계를 여는 거래다.","eSum":"Italian tanker owner Navigazione Montanari is stepping up fleet renewal with two LR2 product tankers ordered at China's Hengli Heavy Industry, booked through Malta-based affiliate Pemont. It opens a new shipbuilding relationship with the fast-growing Dalian yard.","kImp":"제품운반선 신조 발주가 이어지며 탱커 선대 현대화 추세 지속.","eImp":"Continued LR2 ordering underscores an ongoing tanker fleet-renewal wave.","url":"https://splash247.com/pemont-adds-lr2-newbuilds-to-montanari-renewal-push/"},{"code":"TOP","title":"Great Eastern lines up fourth kamsarmax in a year","src":"Splash247","date":"2026-08-11","kSum":"인도 선주 그레이트 이스턴 시핑(Great Eastern Shipping)이 2015년 건조 캄사르막스 벌커를 추가로 인수하기로 하며 1년 새 네 번째 캄사르막스를 확보했다. 인도는 올해 10~12월로 예정됐다.","eSum":"India's Great Eastern Shipping has agreed to acquire another 2015-built kamsarmax, its fourth kamsarmax purchase in a year, with delivery scheduled for October–December. The buying spree reflects steady dry bulk fleet expansion.","kImp":"인도 선주의 벌커 확장 지속으로 중고선 시장 활황 방증.","eImp":"Indian owner's bulker expansion highlights an active secondhand market.","url":"https://splash247.com/great-eastern-lines-up-fourth-kamsarmax-in-a-year/"},{"code":"TOP","title":"Black Sea Grain Exports Squeezed as Danube Hits Record-Low Levels","src":"gCaptain","date":"2026-08-10","kSum":"루마니아를 통한 곡물 물류가 다뉴브강 수위 사상 최저로 제약을 받는 가운데, 러시아의 오데사 등 우크라이나 항만 공습이 곡물 수출을 다른 경로로 몰아가고 있다. 흑해 곡물 공급망에 이중 압박이 가해지고 있다.","eSum":"Black Sea grain exports face fresh constraints as record-low Danube levels restrict flows through Romania, just as escalating Russian strikes divert Ukrainian grain away from Odesa and other ports. The combined pressures are squeezing supply routes.","kImp":"기후·전쟁 이중 요인으로 흑해 곡물 물류 리스크 고조.","eImp":"Drought and war together heighten Black Sea grain logistics risk.","url":"https://gcaptain.com/black-sea-grain-exports-squeezed-as-danube-hits-record-low-levels/"},{"code":"TOP","title":"Turkey Resumes Black Sea Ship Transits Via Straits After Delays","src":"gCaptain","date":"2026-08-09","kSum":"터키가 원인 미상의 지연 조치 이후 흑해로 향하는 선박의 해협 통항을 재개했다. 흑해 선박 공격 급증으로 안보 우려가 커지면서 일부 선박에 대한 통항 지연이 발생한 바 있다.","eSum":"Turkey resumed allowing ships to transit its straits toward the Black Sea following unexplained delays for some vessels amid heightened security concerns. The move eased a temporary bottleneck triggered by a surge in attacks on shipping.","kImp":"흑해 관문인 터키 해협 운영 정상화로 물류 병목 완화.","eImp":"Restored transits ease a bottleneck at the key Black Sea gateway.","url":"https://gcaptain.com/turkey-resumes-black-sea-ship-transits-via-straits-after-delays/"},{"code":"TOP","title":"Turkey Restricts Black Sea Ship Traffic After Surge In Attacks","src":"gCaptain","date":"2026-08-08","kSum":"터키가 러시아·우크라이나의 선박 공격 증가에 대한 우려로 흑해로 진입하는 상선 교통을 제한했다. 이는 흑해 항로의 전쟁 리스크가 상선으로 확산되고 있음을 반영한다.","eSum":"Turkey moved to restrict commercial ship traffic into the Black Sea following growing government concern over an uptick in Russian and Ukrainian attacks on vessels. The step reflects spreading war risk to merchant shipping.","kImp":"흑해 항로 운항 제약으로 곡물·에너지 수출 차질 우려.","eImp":"Traffic curbs raise the risk of disruption to grain and energy exports.","url":"https://gcaptain.com/turkey-restricts-black-sea-ship-traffic-after-surge-in-attacks/"},{"code":"TOP","title":"Shadow Fleet Tanker Captain Sentenced to 10 Months After Weeks-Long Coast Guard Chase","src":"gCaptain","date":"2026-08-11","kSum":"이란·베네수엘라산 석유 운송과 연계된 섀도우 플리트(shadow fleet) 탱커의 전 선장이 미 해안경비대의 정선 명령을 거부하고 수 주간 추격전을 벌인 끝에 연방 교도소 10개월형을 선고받았다. 제재 회피 선단에 대한 미국의 단속 강화를 보여준다.","eSum":"The former master of a shadow fleet tanker linked to Iranian and Venezuelan oil shipments was sentenced to 10 months in federal prison after refusing US Coast Guard orders to stop during a weeks-long chase. It marks intensifying US enforcement against the sanctions-evading fleet.","kImp":"제재 회피 섀도우 플리트에 대한 미국의 형사 단속 본격화.","eImp":"Escalates US criminal enforcement against the sanctions-evading shadow fleet.","url":"https://gcaptain.com/shadow-fleet-tanker-captain-sentenced-to-10-months-after-weeks-long-coast-guard-chase/"},{"code":"TOP","title":"Trump extends controversial Jones Act waiver to mid-November","src":"Seatrade Maritime News","date":"2026-08-11","kSum":"트럼프 행정부가 미국 국내 해운업계의 강한 반대에도 논란이 되고 있는 존스법(Jones Act) 면제 조치를 11월 중순까지 연장했다. 자국 해운 보호와 공급망 대응을 둘러싼 정책 갈등이 이어지고 있다.","eSum":"The Trump administration extended its controversial Jones Act waiver to mid-November despite strong opposition from the US domestic maritime industry. The extension prolongs a policy fight over cabotage protection and supply-chain flexibility.","kImp":"미 연안해운 보호법을 둘러싼 정책 불확실성 지속.","eImp":"Prolongs policy uncertainty over US cabotage protections.","url":"https://www.seatrade-maritime.com/regulations/trump-extends-controversial-jones-act-waiver-to-mid-november"},{"code":"TOP","title":"Asian port congestion forcing container lines back to the Red Sea","src":"Seatrade Maritime News","date":"2026-08-11","kSum":"아시아 주요 항만의 혼잡이 심화되면서 일부 컨테이너 선사들이 홍해 항로 복귀를 검토하고 있다. 희망봉 우회로 늘어난 운항거리와 항만 적체가 서비스 신뢰성을 압박하고 있다.","eSum":"Worsening congestion at major Asian ports is pushing some container lines to consider returning to the Red Sea, as Cape of Good Hope diversions lengthen voyages and strain schedule reliability. The trend signals a possible partial rerouting of global boxship networks.","kImp":"홍해 회귀 움직임은 컨테이너 항로 네트워크 재편의 신호.","eImp":"A potential Red Sea return would reshape container network routing.","url":"https://www.seatrade-maritime.com/containers/asian-port-congestion-forcing-container-lines-back-to-the-red-sea"}]},{"code":"ACC","type":"accident","kTitle":"Section 2. 해양사고","eTitle":"Section 2. Accidents","items":[{"code":"ACC","title":"Car Carrier Abandoned After Catching Fire 630 Miles Off Costa Rica","src":"gCaptain","date":"2026-08-10","kSum":"마셜제도 선적 자동차운반선 '민 장 코우(Min Jiang Kou)'가 코스타리카 남쪽 약 630마일 해상에서 기관실 화재가 발생해 선원 22명이 퇴선했다. 미 해안경비대가 AMVER 시스템으로 인근 상선을 동원했고, '진 하이 핑(Jin Hai Ping)'이 구명정의 전원을 구조했다.","eSum":"The Marshall Islands-flagged car carrier Min Jiang Kou suffered an engine room fire about 630 miles south of Costa Rica, forcing all 22 crew to abandon ship into lifeboats. The US Coast Guard used the AMVER system to divert merchant ships, and the Jin Hai Ping recovered all 22 mariners; no injuries or pollution were reported.","kCause":"기관실 화재. CO2 소화장치로 초기 진화됐으나 이후 연기 증가로 선장이 퇴선을 명령. 정확한 발화 원인은 조사 중.","eCause":"Engine room fire; initially contained by the ship's CO2 system but rising smoke later prompted the abandon-ship order. Exact ignition cause under investigation.","kLes":"원격 해역 기관실 화재 시 CO2 방출 후에도 재발화·연기 확산 위험을 고려한 퇴선 판단과 AMVER 등 상호구조 체계의 중요성이 확인됐다.","eLes":"Remote-ocean engine room fires can reignite or produce spreading smoke after CO2 release; timely abandon-ship decisions and mutual-assistance systems like AMVER are vital.","kImp":"자동차운반선(PCTC) 기관실 화재 위험과 원해 구조 대응 체계의 중요성 재확인.","eImp":"Reaffirms car-carrier engine-room fire risk and the value of long-range rescue coordination.","url":"https://gcaptain.com/car-carrier-abandoned-after-catching-fire-630-miles-off-costa-rica/"},{"code":"ACC","title":"NTSB Blames Unapproved Hot Work for Deadly NYC Sludge Tanker Explosion","src":"gCaptain","date":"2026-08-10","kSum":"미 교통안전위원회(NTSB)는 뉴욕시 하수슬러지 운반선 '헌츠 포인트(Hunts Point)'의 치명적 폭발이 갑판에서의 무허가 열간작업(프로판 토치 사용)에서 비롯됐다고 결론지었다. 승인되지 않은 화기작업이 폭발을 촉발했다.","eSum":"The NTSB determined that the deadly explosion aboard the New York City municipal sludge tanker Hunts Point was triggered by unapproved hot work—use of a propane torch on deck. The finding highlights failures in permit-to-work controls.","kCause":"승인·가스검측 절차를 거치지 않은 갑판 열간작업(프로판 토치)이 가연성 분위기를 점화.","eCause":"Unapproved deck hot work with a propane torch ignited a flammable atmosphere without proper permit or gas-testing.","kLes":"화기작업 허가제(permit-to-work)와 가스 프리(gas-free) 검증을 엄격히 준수해야 하며, 슬러지·오폐수 탱크의 가연성 가스 축적을 경계해야 한다.","eLes":"Strict permit-to-work and gas-free verification are essential; flammable gas can accumulate in sludge/waste tanks.","kImp":"화기작업 관리 실패가 인명 피해로 이어질 수 있음을 보여주는 사례.","eImp":"Shows how hot-work control failures can turn fatal.","url":"https://gcaptain.com/ntsb-blames-unapproved-hot-work-for-deadly-nyc-sludge-tanker-explosion/"},{"code":"ACC","title":"NTSB: Pilot's Personal Phone Call Contributed to Fatal Houston Ship Channel Collision","src":"gCaptain","date":"2026-08-06","kSum":"NTSB는 2024년 휴스턴 선박수로에서 발생한 치명적 충돌의 원인으로 도선사의 장시간 개인 휴대전화 통화와 견시 소홀을 지목했다. 벌크선 '양쯔 7(Yangze 7)'과 예인선단이 얽힌 사고에서 예인선 '미스 페기(Miss Peggy)'가 우현으로 전복됐다.","eSum":"The NTSB found that a Houston pilot's extended personal cell phone call and repeated failures to keep a proper lookout led to a fatal 2024 collision in the Houston Ship Channel, in which the towing vessel Miss Peggy rolled to starboard after contact with the bulk carrier Yangze 7.","kCause":"도선사의 개인 통화 몰입과 적절한 견시 유지 실패로 인한 상황인식 상실.","eCause":"Loss of situational awareness from the pilot's personal phone use and failure to maintain a proper lookout.","kLes":"조선 중 개인 휴대전화 사용 금지와 브리지 자원관리(BRM), 견시 유지의 중요성이 재확인됐다.","eLes":"Reinforces bans on personal phone use while conning, plus bridge resource management and lookout discipline.","kImp":"브리지 주의분산(distraction)이 인명사고로 직결됨을 보여주는 규제·훈련 시사점.","eImp":"Highlights how bridge distraction can be fatal—key for training and regulation.","url":"https://gcaptain.com/ntsb-pilots-personal-phone-call-contributed-to-fatal-houston-ship-channel-collision/"},{"code":"ACC","title":"MSC fined $6m over Charleston runaway probe","src":"Splash247","date":"2026-08-11","kSum":"MSC 십매니지먼트가 2024년 6월 컨테이너선 'MSC 미시간 VII(MSC Michigan VII)'이 찰스턴 항에서 제어 불능으로 16~17노트로 질주한 사건과 관련해 유죄를 인정하고 600만 달러의 형사 벌금과 4년 보호관찰을 선고받았다. 위험 상황 미보고 및 조사 방해가 문제됐다.","eSum":"MSC Shipmanagement pleaded guilty and was fined $6m with four years' probation over the June 2024 incident in which the containership MSC Michigan VII lost engine control and accelerated to 16–17 knots through Charleston Harbor, forcing evacuation of a bridge. The company was penalized for failing to report the hazard and obstructing the NTSB/USCG probe.","kCause":"거버너로 연결되는 링키지 로드가 분리되며 주기관이 전속으로 작동, 선원이 속도 제어 불능. 이후 위험 미보고·조사 방해.","eCause":"A disconnected governor linkage rod left the main engine at full speed with the crew unable to control it; aggravated by failure to report and obstruction.","kLes":"주기관 제어계통 정비·점검의 중요성과 사고 즉시 보고 의무 준수가 강조됐다.","eLes":"Underlines main-engine control-linkage maintenance and the duty to report casualties promptly.","kImp":"기관 제어 상실 사고와 사후 은폐가 대형 형사처벌로 이어질 수 있음을 시사.","eImp":"Shows loss-of-control incidents and cover-ups can bring heavy criminal penalties.","url":"https://splash247.com/msc-fined-6m-over-charleston-runaway-probe/"},{"code":"ACC","title":"MSC boxship sinks deeper off Zhoushan after failed refloating","src":"Splash247","date":"2026-08-08","kSum":"8,401TEU급 20년 선령 컨테이너선 'MSC 실바나 VIII(MSC Silvana VIII)'이 저장(Zhoushan) 앞바다에서 재부양에 실패한 뒤 더 깊이 침수됐다. 선체 대부분이 잠긴 상태로, 여러 화물창과 기관실이 침수됐고 약 3,000톤의 연료유가 제거됐다.","eSum":"The 8,401 teu, 20-year-old containership MSC Silvana VIII has sunk deeper off Zhoushan after refloating attempts failed, with much of the hull now submerged, several cargo holds and the engine room flooded, and about 3,000 tonnes of fuel removed. The salvage now faces another inbound typhoon.","kCause":"저장 수리구역 진입 후 태풍 '바비(Bavi)' 내습 시 좌초, 이후 재부양 실패로 선미부터 침수. 정확한 좌초 원인은 미상.","eCause":"Grounded when Typhoon Bavi struck after entering the Zhoushan repair area; subsequent refloat failure led to stern flooding. Exact grounding cause unclear.","kLes":"수리구역 정박 중 악천후 대비 계류·대피 계획과 침수 확산 시 신속한 연료유 회수·오염방지 대응이 중요하다.","eLes":"Robust foul-weather mooring/evacuation planning and rapid fuel removal/pollution control are critical during yard layups.","kImp":"태풍·좌초로 인한 컨테이너선 전손 위험과 연료유 유출 등 환경 리스크 부각.","eImp":"Highlights typhoon/grounding total-loss risk and bunker pollution exposure.","url":"https://splash247.com/msc-boxship-sinks-deeper-off-zhoushan-after-failed-refloating/"},{"code":"ACC","title":"Ship struck in Gulf of Oman off Pakistan (container ship Vela Nova)","src":"Seatrade Maritime News","date":"2026-08-11","kSum":"파나마 선적 컨테이너선 '벨라 노바(Vela Nova)'가 파키스탄 앞바다 오만만에서 헬기가 발사한 미사일에 피격됐다. 미 해군의 차단(interdiction)으로 추정되며, 화재가 발생했으나 진화됐고 선원 17명 전원이 퇴선 후 안전이 확인됐다. 이란 연계 선박으로 지목됐다.","eSum":"The Panama-flagged container ship Vela Nova was struck by a helicopter-fired missile in the Gulf of Oman about 71nm off Pakistan, in what is believed to be a US Navy interdiction. A fire broke out but was extinguished; all 17 crew abandoned ship and were accounted for. The 30-year-old vessel had been linked to Iran-related shipping.","kCause":"군사적 차단 작전으로 추정되는 미사일 피격. 이란 연계 의심 선박에 대한 단속 강화 정황.","eCause":"Missile strike attributed to a suspected military interdiction amid heightened scrutiny of Iran-linked shipping.","kLes":"오만만·호르무즈 인근 항로의 전쟁·차단 리스크가 상선으로 확대되고 있어 항로계획·보안경계 강화가 필요하다.","eLes":"War and interdiction risk in the Gulf of Oman/Hormuz area is spreading to merchant ships, demanding stronger routing and security vigilance.","kImp":"제재 회피 선단 단속이 실제 선박 피격으로 비화될 수 있음을 보여주는 안보 사건.","eImp":"Shows sanctions enforcement can escalate into actual strikes on vessels.","url":"https://www.seatrade-maritime.com/security/ship-struck-in-gulf-of-oman-off-pakistan"}]},{"code":"PSC","type":"news","kTitle":"Section 3. 항만국통제(PSC)","eTitle":"Section 3. Port State Control","items":[{"code":"PSC","title":"RiSK4SEA PSI Outlook | August 2026: Diverging PSC enforcement recovery leaves bulkers under continued pressure","src":"SAFETY4SEA","date":"2026-08-05","kSum":"RISK4SEA의 2026년 8월 PSC 스트레스지수(PSI) 전망에 따르면 전월까지의 광범위한 악화 이후 글로벌 항만국통제(PSC) 집행 환경이 뚜렷이 완화됐다. 탱커·컨테이너·일반화물선은 'PSI-2 개선 추세'로 복귀했으나, 벌크선만 'PSI-6 성능 악화'에 머물며 유일하게 회복하지 못했다. 탱커는 835건 점검 중 14건 억류로 장기 평균 대비 41.9% 감소하며 가장 강한 회복세를 보였다.","eSum":"RISK4SEA's August 2026 PSC Stress Index (PSI) Outlook reports a clear easing in the global PSC enforcement climate after broad deterioration in prior months. Tankers, containers and general cargo have reverted to 'PSI-2 Improving Trend', while bulkers alone remain under pressure at 'PSI-6 Performance Deteriorating'. Tankers posted the strongest recovery, with only 14 detentions from 835 inspections—down 41.9% versus the long-term average.","kImp":"벌커 선사에 대한 경고 신호로, 화재안전·구명설비·SMS 관련 결함과 상하이·팡청·르자오·다롄·포트켐블라 등 억류 다발 항만에 대한 선제 대응이 요구된다.","eImp":"A warning for bulker operators to address fire-safety, LSA and SMS deficiencies and detention hotspots (Shanghai, Fangcheng, Rizhao, Dalian, Port Kembla) before detention pressure returns.","url":"https://safety4sea.com/cm-risk4sea-psi-outlook-august-2026/"}]},{"code":"PCTC","type":"news","kTitle":"Section 4. 자동차운반선(PCTC)","eTitle":"Section 4. Car Carriers (PCTC)","items":[{"code":"PCTC","title":"Grimaldi Takes Delivery of First New-Series PCTC 'Grande Pacifico'","src":"MarineLink","date":"2026-08-11","kSum":"그리말디 그룹(Grimaldi Group)이 자사 13번째 암모니아-레디 자동차운반선이자 신규 시리즈의 첫 선박인 '그란데 파시피코(Grande Pacifico)'를 인도받았다. 중국 차이나머천츠중공업 장쑤(China Merchants Heavy Industries Jiangsu)가 건조하고 RINA 선급을 취득했으며, 기존 9,000 CEU급 5척에서 진화한 설계로 화물 적재량을 늘리면서도 높은 에너지효율을 유지한다. 전장 220m로 5척 자매선 시리즈의 선두 선박이다.","eSum":"The Grimaldi Group has taken delivery of Grande Pacifico, the 13th ammonia-ready car carrier in its fleet and the first of five sister PCTCs ordered from China Merchants Heavy Industries Jiangsu, classed by RINA. An evolution of the design behind its first five 9,000 CEU vessels, the new units offer greater cargo capacity while maintaining high energy efficiency. The vessel has an overall length of 220 metres.","kImp":"PCTC 선복 부족이 이어지는 가운데 대형·친환경 신조선 인도가 계속되며 선대 확장이 가속되고 있다.","eImp":"Fresh deliveries of large, eco car carriers keep expanding the fleet amid persistent PCTC tonnage tightness.","url":"https://www.marinelink.com/news/grimaldi-takes-delivery-first-newseries-542013"},{"code":"PCTC","title":"Fire ignites on car carrier off Costa Rica; all on board rescued","src":"Baird Maritime","date":"2026-08-10","kSum":"코스타리카 인근 해상에서 코스코쉬핑특수운수(COSCO Shipping Specialized Carriers)가 운항하는 자동차운반선 '민장커우(Min Jiang Kou)'에서 화재가 발생했으나 승선원 전원이 구조됐다. 상하이상선설계연구원(SMDERI)이 설계하고 푸젠조선(Fujian Shipbuilding)이 건조한 선박으로, 사고 원인과 화물 손상 규모는 조사 중이다.","eSum":"A fire broke out on the COSCO Shipping Specialized Carriers PCTC Min Jiang Kou off Costa Rica, with all crew safely rescued. The vessel was designed by the Shanghai Merchant Ship Design and Research Institute and built by Fujian Shipbuilding Industry Group. The cause of the blaze and any cargo damage remain under investigation.","kImp":"차량(특히 EV) 화재 위험이 재부각되며 PCTC 안전·보험 이슈와 함께 선복 공급에도 영향을 줄 수 있다.","eImp":"Another car-carrier fire renews EV cargo-safety and insurance concerns and can tighten PCTC supply.","url":"https://www.bairdmaritime.com/security/incidents/accidents/fire-ignites-on-car-carrier-off-costa-rica-all-on-board-rescued"},{"code":"PCTC","title":"Shanwei accelerates port build for BYD export push","src":"Splash247","date":"2026-08-11","kSum":"중국 광둥성 산웨이(Shanwei)항이 비야디(BYD)의 완성차 수출 물량 급증을 뒷받침하기 위해 전용 터미널 건설에 속도를 내고 있다. 중국 자동차 브랜드의 해외 진출 확대로 로로(RoRo)·PCTC 선적 수요와 항만 인프라 투자가 동반 증가하는 흐름을 보여준다.","eSum":"China's Shanwei port is accelerating construction of dedicated terminal capacity to support surging finished-vehicle exports from BYD. The move underscores how the overseas expansion of Chinese automakers is driving both PCTC/RoRo shipping demand and port infrastructure investment.","kImp":"중국 OEM의 수출 드라이브가 PCTC 물동량과 장기 용선·항만 투자를 견인하는 구조적 수요를 보여준다.","eImp":"Chinese OEM export drive illustrates the structural demand pulling PCTC volumes, long-term charters and port investment.","url":"https://splash247.com/shanwei-accelerates-port-build-for-byd-export-push/"}]},{"code":"WW","type":"news","kTitle":"Section 5. 발레니우스 빌헬름센(WW)","eTitle":"Section 5. Wallenius Wilhelmsen","items":[{"code":"WW","title":"Wallenius Wilhelmsen faces tough choices in Asia as vessel supply sells out","src":"TradeWinds","date":"2026-08-11","kSum":"발레니우스 빌헬름센(Wallenius Wilhelmsen)은 2026년 2분기 실적 발표와 함께 자동차운반선 선복이 극도로 빠듯하며 특히 아시아발 수요가 강하다고 밝혔다. 용선 시장이 타이트해지고 중동發 벙커 비용이 오르면서 추가 선복 확보 비용이 커졌다. 회사는 제한된 가용 선복 속에서 화물 약정을 조율해야 하는 상황이다.","eSum":"Alongside its Q2 2026 results, Wallenius Wilhelmsen says car-carrier vessel supply remains extremely tight, especially out of Asia where demand is strong. Securing extra tonnage has become more expensive as the charter market tightens and Middle East-related bunker costs rise. The company must weigh cargo commitments against limited available capacity.","kImp":"빠듯한 PCTC 선복이 운임을 밀어올리는 동시에 최대 시장에서의 성장 여력을 제약함을 보여준다.","eImp":"Highlights how tight PCTC supply is boosting rates while limiting WW's growth options in its strongest market.","url":"https://www.tradewindsnews.com/finance/wallenius-wilhelmsen-faces-tough-choices-in-asia-as-ships-sell-out/2-1-2027303"},{"code":"WW","title":"Wallenius Wilhelmsen takes oldest PCTCs through 30-year survey amid strong market","src":"Seatrade Maritime","date":"2026-08-11","kSum":"발레니우스 빌헬름센(Wallenius Wilhelmsen)은 1995년 건조된 최고령 PCTC 투란도트(Turandot)와 돈 후안(Don Juan)을 30년 정기검사를 거쳐 통상 퇴역 연령을 넘겨 계속 운항하기로 했다. 견조한 시장에 대한 자신감을 보여주지만 돈 후안은 이후 2026년 2분기에 매각됐다. 빠듯한 선복이 선주들의 선령 연장을 촉진하고 있음을 보여준다.","eSum":"WW has put its oldest PCTCs, the 1995-built Turandot and Don Juan, through 30-year class renewal surveys to keep them trading beyond the usual retirement age. The move reflects confidence in a firm car-carrier market, though Don Juan was subsequently sold in Q2 2026. It underlines how tight tonnage is pushing owners to extend vessel life.","kImp":"최고령 선박의 수명을 연장하며 자동차운반 수요에 대한 낙관을 드러낸다.","eImp":"Signals WW's bullish view on car-carrier demand by extending its oldest ships' working lives.","url":"https://www.seatrade-maritime.com/cargo/shipping-buoys-wallenius-wilhelmsen-in-volatile-market"}]},{"code":"EE","type":"news","kTitle":"Section 6. 에너지효율","eTitle":"Section 6. Energy Efficiency","items":[{"code":"EE","title":"What's wrong with FuelEU","src":"Splash247","date":"2026-08-10","kSum":"머스크(Maersk) 소속 선장 알렉스 뱔랍체프(Alex Byelyavtsev)가 논란의 유럽 규제인 퓨얼EU 마리타임(FuelEU Maritime)의 여섯 가지 문제점을 지적했다. 기후 규제로 홍보됐지만 실제 온실가스 감축 효과와 규제 설계상의 허점이 있다는 비판이다.","eSum":"Maersk master mariner Alex Byelyavtsev identifies six problems with FuelEU Maritime, the controversial European regulation. Sold as a climate rule, he argues its design contains gaps that undercut real greenhouse-gas reductions.","kImp":"FuelEU·EU ETS 등 규제가 복잡해지는 가운데 실효성 논쟁은 선주들의 컴플라이언스 전략에 직접 영향을 준다.","eImp":"Debate over FuelEU's effectiveness directly shapes owners' compliance strategies.","url":"https://splash247.com/whats-wrong-with-fueleu/"},{"code":"EE","title":"Aegis brings 36,000-tonne ammonia terminal online at Pipavav","src":"Splash247","date":"2026-08-11","kSum":"인도에서 이지스(Aegis)가 피파바브(Pipavav)에 36,000톤 규모의 암모니아 터미널을 가동에 들어갔다. 무탄소 선박연료로 주목받는 암모니아의 저장·수출입 인프라가 확충되며 향후 암모니아 벙커링 생태계 형성에 기여할 전망이다.","eSum":"Aegis has brought a 36,000-tonne ammonia terminal online at Pipavav in India. The facility expands storage and import/export infrastructure for ammonia, a leading zero-carbon marine fuel candidate, supporting a future bunkering ecosystem.","kImp":"암모니아 연료의 실용화는 육상 저장·터미널 인프라 확충 여부에 좌우되며, 이번 가동은 그 중요한 진전이다.","eImp":"Ammonia's viability as a fuel hinges on terminal infrastructure; this start-up is a meaningful step.","url":"https://splash247.com/aegis-brings-36000-tonne-ammonia-terminal-online-at-pipavav/"},{"code":"EE","title":"Port of Antwerp-Bruges installs first-of-a-kind AEM electrolyser","src":"Splash247","date":"2026-08-11","kSum":"안트베르펀-브뤼헤항(Port of Antwerp-Bruges)이 세계 최초급 AEM(음이온교환막) 전해조를 설치하며 항만 내 그린수소 생산 역량을 확보했다. 상용 항만 운영 환경에 AEM 전해 기술이 도입되는 사례로, 수소·수소파생연료 공급망 구축의 초기 단계에 해당한다.","eSum":"The Port of Antwerp-Bruges has installed a first-of-a-kind AEM (anion exchange membrane) electrolyser, adding on-site green hydrogen production capacity. It marks the move of AEM electrolysis into commercial port operations, an early building block for hydrogen and hydrogen-derived fuel supply chains.","kImp":"항만발 그린수소 생산은 메탄올·암모니아 등 수소파생 선박연료 공급의 토대가 된다.","eImp":"Port-based green hydrogen underpins future supply of hydrogen-derived marine fuels like methanol and ammonia.","url":"https://splash247.com/port-of-antwerp-bruges-installs-first-of-a-kind-aem-electrolyser/"},{"code":"EE","title":"Technip Energies wins FEED for Malaysian offshore LNG regas terminal","src":"Splash247","date":"2026-08-11","kSum":"테크닙에너지스(Technip Energies)가 말레이시아 케다주의 얀(Yan) 해상 재기화 터미널(RGT Yan) FEED 계약을 수주했다. 연 600만 톤 규모로 해상 FSRU와 해저 가스관, 육상 인수설비를 포함하며, 가스말레이시아·도쿄가스아시아·VTTI가 공동 개발한다. LNG를 활용한 지역 에너지 공급 안정화가 목표다.","eSum":"Technip Energies has won the FEED contract for the Yan offshore regasification terminal (RGT Yan) in Kedah, Malaysia. The 6 mtpa project comprises an offshore FSRU, subsea gas pipeline and onshore receiving facility, jointly developed by Gas Malaysia, Tokyo Gas Asia and VTTI, strengthening regional gas supply.","kImp":"LNG 인프라 확충은 이중연료 LNG 선박의 연료 공급망과 전환 연료 전략을 뒷받침한다.","eImp":"Expanding LNG infrastructure supports the bunkering backbone for LNG dual-fuel shipping.","url":"https://splash247.com/technip-energies-wins-work-on-malaysian-offshore-lng-terminal/"},{"code":"EE","title":"441 m sailing boxship concept dwarfs Emma Maersk","src":"Splash247","date":"2026-08-07","kSum":"전장 441m에 달하는 풍력 추진 컨테이너선 콘셉트가 공개돼 엠마 머스크(Emma Maersk)를 능가하는 규모로 주목받았다. 대형 세일(sail)을 활용한 풍력 보조 추진으로 연료소모와 배출을 줄이려는 차세대 상선 설계 흐름을 보여준다.","eSum":"A 441-metre wind-propulsion container ship concept has been unveiled, dwarfing the Emma Maersk. The design showcases the push toward large sail-assisted propulsion to cut fuel consumption and emissions on next-generation merchant ships.","kImp":"풍력 추진은 CII·FuelEU 대응을 위한 에너지효율 수단으로 관심이 커지고 있다.","eImp":"Wind propulsion is gaining traction as an efficiency lever for CII and FuelEU compliance.","url":"https://splash247.com/441-m-sailing-boxship-concept-dwarfs-emma-maersk/"},{"code":"EE","title":"The problem with percentage savings","src":"Splash247","date":"2026-08-11","kSum":"스플래시테크(SplashTech) 기고에서 선박 에너지효율 기술의 '몇 % 절감' 식 성능 주장에 내재된 함정을 분석했다. 기준선과 측정 방식에 따라 절감률 수치가 왜곡될 수 있어, 실질적 연료·배출 저감 효과를 비교할 때 주의가 필요하다는 지적이다.","eSum":"A SplashTech piece examines the pitfalls in headline 'percentage savings' claims for ship energy-efficiency technologies. Depending on baselines and measurement methods, quoted savings can mislead, so owners must scrutinise real fuel and emissions reductions when comparing solutions.","kImp":"효율 기술 성능 지표의 신뢰성은 투자 의사결정과 CII 성과 예측에 직접 영향을 준다.","eImp":"The credibility of efficiency-tech metrics directly affects investment decisions and CII outcomes.","url":"https://splash247.com/the-problem-with-percentage-savings/"},{"code":"EE","title":"Westports scales up electrification with 60-truck fleet","src":"Splash247","date":"2026-08-11","kSum":"말레이시아 웨스트포츠(Westports)가 전기 트럭 60대를 도입하며 항만 하역·운반 장비 전동화를 확대한다. 항만 운영의 탄소배출과 대기오염을 줄이려는 디카보나이제이션 전략의 일환이다.","eSum":"Malaysia's Westports is scaling up electrification with a fleet of 60 electric trucks, expanding the switch to electric terminal handling equipment. The step is part of a decarbonisation drive to cut port emissions and air pollution.","kImp":"항만 장비 전동화는 스코프1 배출 저감과 그린 코리도어 구축의 핵심 축이다.","eImp":"Terminal electrification is central to cutting Scope 1 emissions and building green corridors.","url":"https://splash247.com/westports-scales-up-electrification-with-60-truck-fleet/"},{"code":"EE","title":"Sumitomo buys into major Celtic Sea floating wind project","src":"Splash247","date":"2026-08-10","kSum":"스미토모(Sumitomo)가 켈틱해(Celtic Sea)의 대형 부유식 해상풍력 프로젝트 지분을 인수했다. 부유식 해상풍력 확대는 그린수소·이퓨얼(e-fuel) 생산을 위한 재생에너지 공급 기반을 넓혀 해운 탈탄소에 간접적으로 기여한다.","eSum":"Sumitomo has bought into a major floating offshore wind project in the Celtic Sea. Scaling floating wind expands the renewable-power base for green hydrogen and e-fuel production, indirectly supporting shipping decarbonisation.","kImp":"재생에너지 확대는 선박용 이퓨얼 생산 단가·가용성 개선의 전제 조건이다.","eImp":"More renewables are a precondition for cheaper, more available marine e-fuels.","url":"https://splash247.com/sumitomo-buys-into-major-celtic-sea-floating-wind-project/"},{"code":"EE","title":"Taiwan's offshore wind project secures $1.7bn financing","src":"Splash247","date":"2026-08-11","kSum":"대만의 한 해상풍력 프로젝트가 17억 달러 규모의 금융조달에 성공했다. 아시아 해상풍력 투자 확대는 청정전력 공급을 늘려 항만 전동화와 수소·이퓨얼 생산 등 해운 탈탄소 인프라를 뒷받침한다.","eSum":"A Taiwanese offshore wind project has secured $1.7bn in financing. Growing Asian offshore wind investment boosts clean-power supply that underpins port electrification and hydrogen/e-fuel production for shipping decarbonisation.","kImp":"아시아 해상풍력 금융 진전은 역내 청정연료·전력 공급망 구축을 가속한다.","eImp":"Progress in Asian offshore wind finance accelerates regional clean-fuel and power supply chains.","url":"https://splash247.com/taiwans-offshore-wind-project-secures-1-7bn-financing/"}]},{"code":"DIG","type":"news","kTitle":"Section 7. 디지털화","eTitle":"Section 7. Digitalization","items":[{"code":"DIG","title":"ShipIn Systems lands $52m to expand AI-powered fleet operations platform","src":"Splash247","date":"2026-08-05","kSum":"해상 기술기업 십인시스템즈(ShipIn Systems)가 AI 기반 선대 운영 플랫폼 확장을 위해 5,200만 달러의 신규 자금을 조달했다. 이 플랫폼은 선상 영상 분석(visual analytics)을 통해 안전·운영 이상을 자동 감지한다.","eSum":"Maritime technology firm ShipIn Systems has secured $52m in fresh financing to expand its AI-powered fleet operations platform. The system uses onboard visual analytics to automatically flag safety and operational anomalies across fleets.","kImp":"선상 AI 영상분석 플랫폼에 대한 대형 투자로 디지털 선대관리 시장이 성숙하고 있음을 보여준다.","eImp":"A major raise signals maturing demand for AI visual-analytics platforms in fleet management.","url":"https://splash247.com/shipin-lands-52m-for-maritime-ai-expansion/"},{"code":"DIG","title":"AI sharpens freight forecasts but cannot tame shipping volatility","src":"Splash247","date":"2026-08-06","kSum":"머신러닝이 해상 운임 예측 도구의 유용성을 높이고 있으나, 28개 연구를 검토한 결과 여전히 확실성보다는 보조 수단에 그친다는 분석이 나왔다. 해운 특유의 변동성은 어떤 모델로도 완전히 길들일 수 없다는 결론이다.","eSum":"Machine learning is making shipping's freight-rate forecasting tools more useful, but a review of 28 studies finds the evidence still points to support rather than certainty. Shipping's inherent volatility remains beyond the reach of any single model.","kImp":"AI 예측의 한계를 짚어 상업팀의 과신을 경계하는 실무적 시사점을 준다.","eImp":"A reality check on AI forecasting limits, cautioning commercial teams against overreliance.","url":"https://splash247.com/ai-sharpens-freight-forecasts-but-cannot-tame-shipping-volatility/"},{"code":"DIG","title":"BIMCO warns against overreliance on AI in contract drafting","src":"Splash247","date":"2026-08-07","kSum":"인공지능이 상업 해운의 계약 업무로 빠르게 확산되고 있으나, 빔코(BIMCO)는 계약 초안 작성에서 인간의 판단이 여전히 필수적이라고 경고했다. 설문조사에서는 AI 계약 초안이 3~5년 내 보편화될 것으로 전망됐다.","eSum":"Artificial intelligence is rapidly moving into commercial shipping's contractual work, but BIMCO has warned that human judgement remains essential in contract drafting. Its survey found AI-generated contracts are expected to become commonplace within three to five years.","kImp":"업계 표준단체가 AI 계약 활용의 리스크 관리 가이드라인 필요성을 공식 제기했다.","eImp":"A leading standards body flags the need for risk guardrails as AI enters contract work.","url":"https://splash247.com/bimco-warns-against-overreliance-on-ai-contract-drafting/"},{"code":"DIG","title":"Shipfinex and ADI Chain target tokenised maritime finance","src":"Splash247","date":"2026-08-11","kSum":"에이디아이체인(ADI Chain)과 십파이넥스(Shipfinex)가 최초의 규제 준수형 기관급 토큰화 해상 금융 플랫폼 구축을 위해 독점 파트너십을 체결했다. 블록체인 기반 자산 토큰화를 통해 선박 금융에 새로운 투자 창구를 열겠다는 구상이다.","eSum":"ADI Chain and Shipfinex have agreed an exclusive partnership to create what they describe as the first regulated, institutional-grade tokenised maritime finance platform. The venture aims to open new investment channels for ship finance via blockchain-based asset tokenisation.","kImp":"블록체인 토큰화가 선박 금융 조달 구조를 바꿀 잠재력을 보여준다.","eImp":"Shows blockchain tokenisation edging into mainstream ship-finance structures.","url":"https://splash247.com/shipfinex-and-adi-chain-target-tokenised-maritime-finance/"},{"code":"DIG","title":"Blue Water Autonomy lands US Navy seabed mapping contract","src":"Splash247","date":"2026-08-05","kSum":"블루워터오토노미(Blue Water Autonomy)가 장기 운항 무인수상정(USV)을 활용한 고해상도 해저 지형 매핑을 위해 미 해군 계약에 선정됐다. 자율운항 선박 기술이 실질적 상업·군용 임무로 확대되고 있음을 보여준다.","eSum":"Blue Water Autonomy has secured a place on a US Navy contract to provide high-resolution seabed mapping using long-endurance uncrewed surface vessels. The award underscores autonomous vessel technology moving into practical commercial and defence missions.","kImp":"자율 무인선의 실전 임무 채택이 기술 성숙도를 방증한다.","eImp":"Real-world uncrewed-vessel deployment demonstrates rising autonomy maturity.","url":"https://splash247.com/blue-water-autonomy-lands-us-navy-seabed-mapping-contract/"},{"code":"DIG","title":"Global Mercy hospital ship completes digital survey and inclining test","src":"Smart Maritime Network","date":"2026-08-05","kSum":"세계 최대 민간 병원선 글로벌머시(Global Mercy)호가 디지털 방식의 경량 검사와 경사시험(inclining test)을 완료했다. 종이 기반 절차를 대체하는 디지털 계측·기록 방식이 대형 선박 검사에도 적용되고 있음을 보여준다.","eSum":"The Global Mercy, the world's largest purpose-built civilian hospital ship, has completed a lightweight survey and inclining test using digital methods. It illustrates digital measurement and recording replacing paper-based procedures even on large vessels.","kImp":"디지털 선급 검사가 대형선 실무로 확산되는 사례다.","eImp":"A concrete case of digital class surveys reaching large-vessel practice.","url":"https://smartmaritimenetwork.com/2026/08/05/global-mercy-hospital-ship-completes-digital-survey/"},{"code":"DIG","title":"Former ZeroNorth CEO launches maritime tech advisory Tidely Partners","src":"Splash247","date":"2026-08-05","kSum":"제로노스(ZeroNorth) 전 CEO 쇠렌 크리스티안 마이어(Søren Christian Meyer)가 코펜하겐 기반 자문사 타이들리파트너스(Tidely Partners)를 설립했다. 투자자와 기술기업, 선사를 대상으로 해상 디지털 전환 자문을 제공한다.","eSum":"Former ZeroNorth chief executive Søren Christian Meyer has launched Tidely Partners, a Copenhagen-based advisory firm targeting investors, technology companies and shipowners. It will advise on maritime digital transformation strategy.","kImp":"해상 디지털 전환 자문 수요 증가와 인재 이동을 보여준다.","eImp":"Reflects growing demand for maritime digital-transformation advisory and talent flow.","url":"https://splash247.com/former-zeronorth-boss-launches-maritime-tech-advisory/"},{"code":"DIG","title":"OceanPal goes shipless in AI pivot","src":"Splash247","date":"2026-08-06","kSum":"나스닥 상장사 오션팔(OceanPal)이 잔여 선대를 보유한 지주사를 매각하며 해운업에서 완전히 철수하고 AI 사업으로 전환했다. 전통 선주가 디지털·AI 사업 모델로 방향을 트는 이례적 사례다.","eSum":"Nasdaq-listed OceanPal has completed its exit from shipping, selling the holding company behind its remaining fleet as it pivots fully to AI. It is a striking case of a traditional shipowner reorienting toward a digital/AI business model.","kImp":"선주가 자산 기반에서 디지털 사업으로 전환하는 구조적 변화의 신호다.","eImp":"Signals a structural shift from asset ownership toward digital business models.","url":"https://splash247.com/oceanpal-goes-shipless-in-ai-pivot/"},{"code":"DIG","title":"China's AI push is a trade story","src":"Splash247","date":"2026-08-11","kSum":"진짜 AI 경쟁은 가장 똑똑한 모델을 만드는 쪽이 아니라 지능을 가장 빠르게 산업에 내재화하는 쪽이 이긴다는 분석이다. 중국의 AI 확산이 무역·해운 구조에 미치는 함의를 짚었다.","eSum":"The real AI contest may not be won by whoever builds the smartest model, but by whoever embeds intelligence fastest across industry. The piece frames China's AI push in terms of its trade and shipping implications.","kImp":"AI 도입 속도가 해운·무역 경쟁력의 새로운 축이 되고 있음을 시사한다.","eImp":"Suggests speed of AI adoption is becoming a new axis of trade and shipping competitiveness.","url":"https://splash247.com/chinas-ai-push-is-a-trade-story/"}]},{"code":"TECH","type":"news","kTitle":"Section 8. 선박기술","eTitle":"Section 8. Ship Technical","items":[{"code":"TECH","title":"KCC takes delivery of final CABU III combination carrier MV Baltazar","src":"MarineLink","date":"2026-08-09","kSum":"클라베네스컴비네이션캐리어스(KCC)가 뉴양쯔 조선소에서 3세대 CABU 선박의 마지막 선박인 MV 발타자르(Baltazar)를 인도받았다. 이 선박은 KCC 선대 최초의 풍력 보조 추진 시스템과 다양한 에너지효율 기술을 탑재해 CABU III 신조 프로그램을 완성했다.","eSum":"Klaveness Combination Carriers (KCC) has taken delivery of MV Baltazar, its third and final third-generation CABU vessel, from New Yangzi Shipyard. It is equipped with the first wind-assisted propulsion system in KCC's fleet plus a range of energy efficiency technologies, completing the CABU III newbuilding program.","kImp":"풍력 보조 추진과 에너지효율 기술을 결합한 신조선 인도로 기술팀의 저탄소 운항 대응 사례를 제시한다.","eImp":"A newbuild pairing wind-assist and efficiency tech gives technical teams a low-carbon reference.","url":"https://www.marinelink.com/news/kcc-takes-delivery-final-cabu-iii-541922"},{"code":"TECH","title":"ABB to power Allseas' heavy transport vessel Grand Tour","src":"MarineLink","date":"2026-08-11","kSum":"ABB가 광저우조선국제(GSI)에서 건조되는 알시즈(Allseas)의 230m급 반잠수식 중량물 운반선 그랜드투어(Grand Tour)에 통합 전력·추진 시스템을 공급한다. 2028년 인도 예정인 이 선박은 아시아·유럽에서 제작된 대형 해상풍력 변환소를 운송·이송하도록 설계됐다.","eSum":"ABB will supply the integrated power and propulsion system for Grand Tour, a 230-metre semi-submersible heavy transport vessel being built by Guangzhou Shipyard International (GSI) for Allseas. Due for delivery in 2028, the ship is designed to transport large offshore wind converter stations from Asian and European fabrication yards.","kImp":"대형 전력·추진 통합 패키지 수주로 특수선 기술 트렌드를 보여준다.","eImp":"A major integrated power-and-propulsion award illustrates specialised-vessel technology trends.","url":"https://www.marinelink.com/news/abb-power-allseas-heavy-transport-vessel-541977"},{"code":"TECH","title":"AI boom puts shipowners in race with tech giants for engines","src":"Splash247","date":"2026-08-10","kSum":"HD현대중공업이 자사 최대 규모의 발전용 엔진 공급 계약을 따내며, AI 붐이 촉발한 데이터센터 전력 수요가 선박용 엔진 제조 경쟁 구도를 바꾸고 있음을 보여줬다. 선주들이 전력 수요가 급증하는 테크 대기업과 엔진 확보 경쟁을 벌이는 양상이다.","eSum":"HD Hyundai Heavy Industries has landed its largest-ever power-generation engine contract, underlining how the AI-driven surge in data-centre power demand is reshaping competition for marine engine capacity. Shipowners increasingly find themselves competing with tech giants for engine slots.","kImp":"엔진 제조 캐파 경쟁 심화는 신조·수리 발주 리드타임에 직접 영향을 준다.","eImp":"Tightening engine-maker capacity directly affects newbuild and repair lead times.","url":"https://splash247.com/ai-boom-puts-shipowners-in-race-with-tech-giants-for-engines/"},{"code":"TECH","title":"CMT brings rapid onboard oil analysis to SMM","src":"Splash247","date":"2026-08-11","kSum":"독일 상태감시 전문업체 CM테크놀로지스(CMT)가 함부르크 SMM에서 소형 오일 분석기를 선보인다. 선상에서 신속한 윤활유 분석을 가능하게 해 정비 판단을 앞당기고 기관 손상을 조기에 파악할 수 있다.","eSum":"German condition monitoring specialist CM Technologies is set to showcase a compact onboard oil analyser at SMM in Hamburg. The device enables rapid lubricant analysis at sea, helping crews advance maintenance decisions and catch machinery wear early.","kImp":"선상 상태감시 장비의 진화로 예지정비 실무가 강화된다.","eImp":"Advancing onboard condition-monitoring tools strengthens predictive-maintenance practice.","url":"https://splash247.com/cmt-brings-rapid-onboard-oil-analysis-to-smm/"},{"code":"TECH","title":"Hamworthy returns with renewed focus on marine water and waste systems","src":"MarineLink","date":"2026-08-10","kSum":"영국 해양 물·폐기물 처리 전문업체 햄워시(Hamworthy)가 브랜드를 재출범하며, 환경 시스템이 부가 장비에서 현대 해운의 핵심 인프라로 진화했다고 강조했다. 14년간 바르질라(Wärtsilä) 그룹의 물·폐기물 사업부였던 조직이 독립 브랜드로 복귀했다.","eSum":"British marine water and waste specialist Hamworthy has relaunched, with CEO Fraser Scott stressing that environmental systems have evolved from check-box auxiliaries into core infrastructure of modern shipping. The unit returns as an independent brand after 14 years as Wärtsilä Group's water and waste division.","kImp":"환경 처리 장비의 위상 변화는 기술팀의 설비 관리 우선순위를 재편한다.","eImp":"The rising status of environmental systems reshapes technical-team equipment priorities.","url":"https://www.marinelink.com/news/hamworthy-returns-renewed-focus-future-541936"},{"code":"TECH","title":"TANAKA develops sulphur-resistant methane slip catalyst","src":"Splash247","date":"2026-08-05","kSum":"일본 다나카귀금속(TANAKA)이 가스 엔진의 메탄 슬립을 줄이도록 설계된 내황성 메탄 산화 촉매를 개발했다. 황 성분에 강한 특성으로 실제 운항 조건에서의 촉매 성능 저하 문제를 완화하는 것을 목표로 한다.","eSum":"Japan's TANAKA Precious Metal Technologies has developed a methane oxidation catalyst designed to cut methane slip from gas engines while resisting sulphur poisoning. The sulphur tolerance aims to address catalyst degradation under real operating conditions.","kImp":"LNG 엔진의 메탄 슬립 저감 기술은 온실가스 규제 대응의 핵심 과제다.","eImp":"Methane-slip abatement for gas engines is central to meeting GHG regulation.","url":"https://splash247.com/tanaka-develops-sulphur-resistant-methane-slip-catalyst/"},{"code":"TECH","title":"441 m sailing boxship concept dwarfs Emma Maersk","src":"Splash247","date":"2026-08-07","kSum":"대형 고체 세일과 태양광, 배터리, 수소 또는 전기 추진을 결합한 441.5m급 초대형 컨테이너선 콘셉트가 공개됐다. 엠마머스크(Emma Maersk)를 능가하는 규모로 미래 무탄소 추진 조합의 가능성을 제시한다.","eSum":"A radical 441.5-metre ultra-large containership concept combining giant solid sails, solar power, batteries and hydrogen or electric propulsion has been unveiled. Dwarfing the Emma Maersk, it explores future zero-carbon propulsion combinations.","kImp":"복합 추진 콘셉트는 차세대 대형선 설계 방향을 가늠하게 한다.","eImp":"A multi-source propulsion concept hints at next-generation large-ship design.","url":"https://splash247.com/441-m-sailing-boxship-concept-dwarfs-emma-maersk/"},{"code":"TECH","title":"CNOOC's new LNG carrier named Greenergy River","src":"MarineLink","date":"2026-08-05","kSum":"NYK가 참여하는 합작사 HLT가 CNOOC그룹을 위한 신조 LNG 운반선 그리너지리버(Greenergy River)호 명명식을 후동중화조선에서 개최했다. 중국 국영 에너지사의 LNG 운송 선대 확충을 뒷받침하는 신조선이다.","eSum":"HLT, a joint venture in which NYK participates, held a naming ceremony for a new LNG carrier, Greenergy River, built for China's CNOOC Group at Hudong-Zhonghua Shipbuilding. The newbuild supports the state energy company's growing LNG transport fleet.","kImp":"대형 LNG 운반선 신조 인도로 가스선 건조 사이클의 지속을 보여준다.","eImp":"A large LNG carrier delivery reflects the continuing gas-carrier newbuild cycle.","url":"https://www.marinelink.com/news/cnoocs-lng-vessel-named-greenergy-river-541808"},{"code":"TECH","title":"Dajin Heavy delivers second KING-class offshore wind logistics vessel","src":"MarineLink","date":"2026-08-05","kSum":"중국 해상풍력 기초구조물 제조사 다진중공업(Dajin Heavy Industry)이 자체 개발한 40,000DWT급 중량갑판 운반선 KING 시리즈의 두 번째 선박 KING TWO를 인도했다. 전장 239.8m, 폭 51m 규모로 표준화 양산 체제로의 전환을 알렸다.","eSum":"China-based offshore wind foundations manufacturer Dajin Heavy Industry has delivered KING TWO, the second 40,000 DWT heavy deck carrier in its self-developed KING series. At 239.8 m in length and 51 m in beam, it marks a shift into standardised batch construction.","kImp":"해상풍력 물류 특수선의 양산 전환은 관련 신조 수요 확대를 시사한다.","eImp":"Batch production of offshore-wind logistics vessels signals expanding newbuild demand.","url":"https://www.marinelink.com/news/dajin-heavy-delivers-second-kingclass-541794"}]},{"code":"HR","type":"news","kTitle":"Section 9. 해원/인사","eTitle":"Section 9. Marine HR","items":[{"code":"HR","title":"Career Paths: Stella Aber, Head of Programmes at The Seafarers' Charity","src":"SAFETY4SEA","date":"2026-08-05","kSum":"세이프티포시(SAFETY4SEA)의 '커리어 패스(Career Paths)' 인터뷰에서 더 시퍼러스 채리티(The Seafarers' Charity)의 프로그램 총괄 스텔라 에이버(Stella Aber)는 정책·옹호·파트너십·프로그램 실행을 결합해 선원의 삶을 실질적으로 개선하는 데서 동기를 얻는다고 밝혔다. 그는 선원 복지를 별개의 이슈가 아니라 해운 정책과 산업 성과의 핵심 요소로 다뤄야 한다고 강조했다. 지속적인 학습과 적응력이 커리어에서 가장 가치 있는 투자였다고 조언했다.","eSum":"In SAFETY4SEA's Career Paths interview, Stella Aber, Head of Programmes at The Seafarers' Charity, says she is driven by making practical, lasting improvements to seafarers' lives by combining policy, advocacy, partnerships and programme delivery. She argues seafarer welfare should be treated as integral to maritime policy and industry performance, not a separate issue. She cites continuous learning and adaptability as the most valuable career investments.","kImp":"선원 복지를 산업 전략의 핵심으로 끌어올리려는 복지단체 리더십의 방향을 보여준다.","eImp":"Signals welfare-charity leadership pushing seafarer wellbeing to the core of industry strategy.","url":"https://safety4sea.com/cm-career-paths-stella-aber-the-seafarers-charity/"},{"code":"HR","title":"Career Paths: Namrata Nadkarni, Founder & CEO of Intent Communications","src":"SAFETY4SEA","date":"2026-08-06","kSum":"세이프티포시 '커리어 패스' 인터뷰에서 인텐트 커뮤니케이션즈(Intent Communications) 창업자 겸 CEO 남라타 나드카르니(Namrata Nadkarni)는 22년 이상의 해운 경력을 바탕으로 열린 마음과 가치관, 관계를 최우선하라고 조언했다. 그는 기술 지식과 사람을 다루는 역량이 결합될 때 최선의 성과가 나온다고 강조했다. 아울러 업계가 실수에 대해 더 솔직하게 지식을 공유해 신뢰를 쌓아야 한다고 촉구했다.","eSum":"In SAFETY4SEA's Career Paths interview, Namrata Nadkarni, founder and CEO of Intent Communications, draws on more than 22 years in shipping to advise keeping an open mind, staying true to one's values and prioritising relationships. She stresses that people skills combined with technical knowledge deliver the best results. She also calls for more honest knowledge-sharing about mistakes to build trust across maritime.","kImp":"해운 인재 개발과 리더십에서 소프트 스킬과 개방적 문화의 중요성을 부각한다.","eImp":"Highlights soft skills and open culture as central to maritime talent development.","url":"https://safety4sea.com/cm-career-paths-namrata-nadkarni-intent-communications/"},{"code":"HR","title":"Maersk sells training arm to OpenGate","src":"Splash247","date":"2026-08-10","kSum":"머스크(Maersk)가 40년 역사의 교육 사업부 머스크 트레이닝(Maersk Training)과 자회사 머스크 H2S 세이프티 서비스를 미국 사모펀드 오픈게이트 캐피털(OpenGate Capital)에 매각하기로 합의했다. 거래 금액은 비공개이며 규제 승인을 거쳐 연내 완료될 예정이다. 이 사업부는 해운·해양에너지·재생에너지·물류 전반의 역량 개발과 안전 교육을 제공해 왔으며, 머스크는 핵심 물류 브랜드 집중을 매각 배경으로 들었다.","eSum":"Maersk has agreed to sell its four-decade-old training business, Maersk Training, and subsidiary Maersk H2S Safety Services to US private equity firm OpenGate Capital, with terms undisclosed and completion expected this year subject to regulatory approval. The unit provides competency development and safety training across maritime, offshore energy, renewables and logistics. Maersk framed the divestment as part of its focus on core logistics brands.","kImp":"대형 선사가 선원·안전 교육 사업을 분리하며 훈련 시장 재편 신호를 준다.","eImp":"A major carrier spinning off crew and safety training signals a reshaping of the maritime training market.","url":"https://splash247.com/maersk-sells-training-arm-to-opengate/"},{"code":"HR","title":"Shipping's talent shortage is partly self-inflicted","src":"Seatrade Maritime News","date":"2026-08-11","kSum":"코펜하겐 비즈니스 스쿨의 아이린 로스버그(Irene Rosberg)는 시트레이드(Seatrade) 기고에서 해운 인력난이 부분적으로 자초한 것이라고 주장했다. BIMCO/ICS 선원인력보고서는 2026년 STCW 사관 3만9,100명 부족과 2030년까지 추가 11만3,735명 필요를 전망하는데, 그는 50세 이상 숙련 인력을 외면하는 관행을 원인으로 지목했다. 공정한 평가와 재교육, 다세대 팀 구성, 숙련 선원의 육상 전환을 해법으로 제시했다.","eSum":"Writing in Seatrade Maritime News, Copenhagen Business School's Irene Rosberg argues the maritime skills shortage is partly self-inflicted because employers overlook experienced professionals aged 50 and over. She cites the BIMCO/ICS Seafarer Workforce Report projecting a 39,100-officer shortfall in 2026, with a further 113,735 officers needed by 2030. She urges fairer assessment of older candidates, reskilling, multigenerational teams and moving experienced seafarers into shore roles.","kImp":"사관 부족 심화 속에서 고령 숙련 인력 활용이라는 대안적 해법을 제기한다.","eImp":"Offers an alternative fix — tapping older experienced talent — as the officer shortfall deepens.","url":"https://www.seatrade-maritime.com/ship-operations/shipping-s-talent-shortage-is-partly-self-inflicted"}]},{"code":"HSEQ","type":"news","kTitle":"Section 10. HSEQ","eTitle":"Section 10. HSEQ","items":[{"code":"HSEQ","title":"Lessons learned: Safety-critical systems must be designed to withstand failure","src":"SAFETY4SEA","date":"2026-08-06","kSum":"세이프티포시가 소개한 CHIRP 머라리팀(CHIRP Maritime) 사례에서, 조난선을 지원하러 출동한 구조선이 혼잡한 해역에서 RAM(조종 제한) 등화를 표시한 직후 전기 화재가 발생했다. 핵심 교훈은 안전 필수 시스템에 단일 고장이 선박 기능을 마비시키지 않도록 이중화·페일세이프를 설계해야 한다는 점이다. 특히 구조 자산으로 활동할 때 이러한 설계가 더욱 중요하다.","eSum":"In a CHIRP Maritime case shared by SAFETY4SEA, a rescue vessel responding to a disabled ship suffered an electrical fire shortly after displaying RAM (restricted in ability to manoeuvre) lights in a busy traffic area. The key lesson: safety-critical systems must be engineered with redundancy and fail-safes so a single failure does not incapacitate the vessel — especially when it is itself the rescue asset.","kImp":"구조 자산조차 단일 고장에 취약할 수 있어 이중화 설계의 중요성을 환기한다.","eImp":"Even a rescue asset can be crippled by a single fault, underlining the need for redundancy.","url":"https://safety4sea.com/lessons-learned-safety-critical-systems-must-be-designed-to-withstand-failure/"},{"code":"HSEQ","title":"Tanker taken to anchorage after smoke alarm in Çanakkale Strait","src":"SAFETY4SEA","date":"2026-08-06","kSum":"케미컬 탱커 하브바 아나(Havva Ana)호가 8월 5일 차낙칼레 해협(Çanakkale Strait, 다르다넬스) 통항 중 굴뚝에서 짙은 연기가 관측돼 셰브케티예(Şevketiye) 정박지로 유도됐다. 해사당국과 예인선이 대응했고, 선박은 예방 차원에서 정박됐다.","eSum":"The chemical tanker Havva Ana was directed to the Şevketiye anchorage on 5 August after heavy smoke was seen coming from its funnel while transiting the Çanakkale Strait (Dardanelles). Maritime authorities and tugs responded, and the vessel was anchored as a precaution.","kImp":"주요 해협 통항 중 기관 이상 조기 대응 절차의 중요성을 보여준다.","eImp":"A reminder of the value of early engine-fault response during transits of a critical strait.","url":"https://safety4sea.com/tanker-taken-to-anchorage-after-smoke-alarm-in-canakkale-strait/"},{"code":"HSEQ","title":"MSF: Complacency during tubular cargo operations","src":"SAFETY4SEA / Marine Safety Forum","date":"2026-08-10","kSum":"마린 세이프티 포럼(Marine Safety Forum, MSF) 안전속보에 따르면, 13인치 케이싱 파이프를 3개 묶음으로 하역하던 중 슬링 해제 과정에서 하중이 불안정해져 파이프가 굴러 한 선원의 왼쪽 발목을 다치게 했다. 작업 전 툴박스 미팅이 있었음에도 일상 작업에 대한 안이함(complacency)이 주원인으로 지목됐다. 툴박스 미팅이 위험·통제·역할·작업중지권한을 명확히 공유하는 실질적 안전장벽이 돼야 한다는 교훈이다.","eSum":"A Marine Safety Forum (MSF) safety flash reports that while landing 13-inch casing pipes in bundles of three, a load lost stability during sling disconnection, causing pipes to roll and injure a crew member's left ankle. Despite a prior toolbox talk, MSF attributes the incident largely to complacency during a routine task. The lesson: toolbox talks must act as a genuine safety barrier that clearly conveys hazards, controls, roles and stop-work authority.","kImp":"반복 작업의 안이함이 사고로 이어지는 전형적 사례로 툴박스 미팅의 실효성을 강조한다.","eImp":"A classic case of routine-task complacency, stressing the real value of effective toolbox talks.","url":"https://safety4sea.com/msf-complacency-during-tubular-cargo-operations/"},{"code":"HSEQ","title":"Sulphuric acid tanker suffers explosion during repairs off Norway","src":"SAFETY4SEA","date":"2026-08-11","kSum":"황산을 실은 탱커가 8월 10일 노르웨이 흐발레르(Hvaler) 인근 스카게라크(Skagerrak) 해역에서 수리 작업 중 폭발과 화재가 발생했으나 선원 15명은 전원 무사했다. 노르웨이 당국은 구조 헬기와 순찰정을 투입했고, 선원들은 폼으로 화재를 진압하고 선체를 냉각했다. 점검 결과 황산 화물의 오염이나 누출은 확인되지 않았으며 원인은 조사 중이다.","eSum":"A tanker carrying sulphuric acid suffered an explosion and fire during repair work in the Skagerrak off Hvaler, Norway, on 10 August; all 15 crew were unharmed. Norwegian authorities deployed rescue helicopters and patrol boats, while the crew used foam to fight the fire and cooled the hull with water. An inspection found no pollution or release of the acid cargo, and the cause is under investigation.","kImp":"위험물 운반선의 수리 중 화재 위험과 선원 비상대응 역량을 부각한다.","eImp":"Underlines fire risks during repairs on hazardous-cargo tankers and the value of crew emergency response.","url":"https://safety4sea.com/sulphuric-acid-tanker-suffers-explosion-during-repairs-off-norway/"}]},{"code":"KR","type":"news","kTitle":"Section 11. 한국해운","eTitle":"Section 11. Korean Shipping","items":[{"code":"KR","title":"HMM 소속 프리미어얼라이언스, 부산-美 동안 EC3 노선 개편…中 닝보 신규 취항","src":"코리아쉬핑가제트","date":"2026-08-12","kSum":"HMM·일본 ONE·대만 양밍으로 구성된 프리미어얼라이언스가 아시아-북미 동안을 잇는 EC3 항로에 중국 닝보를 신규 기항한다. 부산과 태국 램차방 사이에 닝보를 추가해 중국 기항지를 톈진·칭다오 포함 3곳으로 늘렸으며, HMM 페리도트호가 9월19일 부산 출항 후 20일 닝보에 첫 입항한다.","eSum":"Premier Alliance (HMM, ONE, Yang Ming) will add China's Ningbo as a new call on its Asia-US East Coast EC3 service, raising its China port calls to three. HMM's Peridot makes the first Ningbo call on Sept 20.","kImp":"HMM의 북중국 기항 확대는 현지 물류 수요 증가에 대응하고 프리미어얼라이언스의 북미 동안 서비스 경쟁력을 강화하려는 전략이다.","eImp":"Expanding North China coverage strengthens Premier Alliance's US East Coast competitiveness and HMM's access to growing regional cargo.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147736"},{"code":"KR","title":"북미항로 상반기 실적 '동남아 웃고 동북아 울고'…한국 2년 연속 감소, 태국에 밀려 4위","src":"코리아쉬핑가제트","date":"2026-08-12","kSum":"2026년 1~6월 아시아 18개국의 대미 수출 컨테이너 물동량은 1078만5000TEU로 전년比 0.3% 늘어 역대 두 번째를 기록했다. 베트남(+10%)·태국(+21%)·인도네시아(+11%)가 사상 최고치를 쓴 반면, 1위 중국과 4위 한국은 2년 연속 감소했고 한국은 처음으로 3위를 태국에 내줬다.","eSum":"H1 2026 Asia-US container exports reached 10.79m TEU (+0.3% YoY), the second-highest ever. Vietnam, Thailand and Indonesia hit records while China and Korea fell for a second year — Korea slipping to 4th behind Thailand.","kImp":"한국 화주·선사의 대미 수출 물량 위축은 국내 컨테이너 해운 경쟁력 약화 신호로, 동남아 생산기지 이전이 물동량 지형을 바꾸고 있음을 보여준다.","eImp":"Korea's declining US-bound volumes signal weakening competitiveness as production shifts to Southeast Asia reshape trade flows.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147778"},{"code":"KR","title":"'韓中 웃고 日 울고' 상반기 선박 수주량 희비교차…한국 수주 전년比 60% 급증","src":"코리아쉬핑가제트","date":"2026-08-06","kSum":"클락슨에 따르면 2026년 상반기 글로벌 신조 발주량은 전년比 66% 급증한 4295만CGT로 2년 만에 4000만t을 돌파했다. 한국은 797만t으로 전년比 60% 늘며 세계 2위, 중국은 3100만t으로 1위, 일본은 68만t으로 6년 만에 100만t을 밑돌았다. 원유·가스 운반선과 해양플랜트가 한국 조선소 수주를 견인했다.","eSum":"Clarksons data shows H1 2026 global newbuilding orders surged 66% to 43.0m CGT. Korea took 2nd at 7.97m CGT (+60% YoY), behind China's 31.0m CGT, while Japan fell below 1m t for the first time in six years.","kImp":"중동 전쟁발 에너지 공급망 다변화로 탱커·가스선 발주가 급증하며 한국 조선소(HD현대·삼성중공업·한화오션)의 고부가 선종 수주 여건이 크게 개선됐다.","eImp":"Middle East war-driven energy supply diversification is boosting tanker and gas-carrier orders, benefiting Korea's high-value shipbuilders.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147748"},{"code":"KR","title":"덴마크 머스크, HD현대삼호서 초대형 암모니아운반선(VLAC) 첫 인도받아","src":"코리아쉬핑가제트","date":"2026-08-06","kSum":"HD현대삼호가 회사 최초로 9만3000㎥급 초대형 암모니아 운반선 '제인머스크'호를 덴마크 머스크에 인도했다. 총 10척 시리즈 중 첫 호선으로 2028년 9월까지 순차 인도되며, 액화 암모니아·LPG 모두 운송 가능하다. HD현대삼호는 7월27일 기준 올해 30척·40억8000만달러를 수주해 목표 49억달러의 83%를 달성했다.","eSum":"HD Hyundai Samho delivered its first 93,000㎥ VLAC, 'Jane Maersk', to Denmark's Maersk — the first of a 10-ship series running to Sept 2028. The yard has booked $4.08bn (30 ships) so far in 2026, 83% of target.","kImp":"암모니아 운반선은 차세대 무탄소 연료 공급망의 핵심 선종으로, HD현대삼호의 첫 VLAC 인도는 한국 조선소의 친환경 고부가 선박 경쟁력을 입증한다.","eImp":"Ammonia carriers are key to future zero-carbon fuel chains; the first VLAC delivery proves Korean yards' edge in green high-value vessels.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147773"},{"code":"KR","title":"HD현대, 美 최대 방산 조선사 헌팅턴 잉걸스와 손잡고 함정 건조 생산성 높인다","src":"코리아쉬핑가제트","date":"2026-08-07","kSum":"HD현대가 미국 최대 수상함 건조 조선소인 헌팅턴 잉걸스 산하 잉걸스조선소에서 생산성 향상 시범사업에 착수했다. 2025년 체결한 첨단 조선기술 협력 MOU의 일환으로, HD현대가 자체 개발한 지능형 용접 시스템을 미시시피주 잉걸스조선소에 도입해 로봇 자동 용접·실시간 품질관리를 구현한다.","eSum":"HD Hyundai launched a productivity pilot at Ingalls Shipbuilding, a unit of top US naval builder Huntington Ingalls, deploying its intelligent welding system under a 2025 advanced-shipbuilding MOU.","kImp":"미국 방산 조선 협력은 한국 조선소가 미 해군 함정 유지·건조 시장에 진출하는 발판으로, 한미 조선동맹 강화의 상징적 사례다.","eImp":"US naval shipbuilding cooperation is a foothold for Korean yards into the US Navy MRO and newbuild market, symbolizing a strengthening alliance.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147793"},{"code":"KR","title":"남성해운, 국내 최대 편의점 CU와 공급망 개척 '맞손'","src":"코리아쉬핑가제트","date":"2026-08-11","kSum":"창립 73주년을 맞은 남성해운이 국내 최대 편의점 브랜드 CU(BGF리테일)와 손잡고 아시아 역내 공급망 개척에 나선다. 인트라아시아 컨테이너 선사인 남성해운은 CU의 해외 물류 수요를 지원하며 신규 화물 확보를 노린다.","eSum":"Namsung Shipping, marking its 73rd anniversary, partnered with Korea's largest convenience-store chain CU (BGF Retail) to develop intra-Asia supply-chain business and secure new cargo.","kImp":"인트라아시아 선사와 대형 유통기업의 협력은 안정적 화물 기반 확보 사례로, 중소 국적 선사의 물동량 다변화 전략을 보여준다.","eImp":"A carrier-retailer tie-up secures stable cargo, illustrating volume-diversification strategy for mid-sized Korean lines.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147771"},{"code":"KR","title":"한진, 베네수엘라 지진 구호물자 운송 맡는다","src":"코리아쉬핑가제트","date":"2026-08-11","kSum":"물류기업 한진이 베네수엘라 지진 피해 이재민에게 전달할 한국 정부의 긴급 구호물자 운송을 담당한다. 정부 지원 국제 인도적 물류 사업을 한진이 수행하며 재난 대응 특수 화물 처리 역량을 보인다.","eSum":"Logistics firm Hanjin will transport the Korean government's emergency relief supplies to earthquake victims in Venezuela.","kImp":"정부 구호물자 운송 수임은 한진의 국제 프로젝트·특수 물류 역량과 공공부문 신뢰도를 보여주는 사례다.","eImp":"Winning the government relief contract showcases Hanjin's international project-logistics capability and public-sector trust.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147813"},{"code":"KR","title":"한국해운조합, 김학범 신임 동남권역본부장 선출","src":"코리아쉬핑가제트","date":"2026-08-11","kSum":"한국해운조합(KSA)이 8월11일 제2회 임시총회를 열고 김학범 신임 동남권역본부장을 선출했다. 부산·경남 등 동남권 연안·내항 해운업계를 대표하는 조직 인선이 마무리됐다.","eSum":"The Korea Shipping Association elected Kim Hak-beom as its new Southeastern Regional Head at an Aug 11 extraordinary general meeting.","kImp":"동남권역본부는 국내 연안해운 이해를 대변하는 핵심 조직으로, 신임 본부장 선출은 연안 해운정책 창구의 리더십 변화를 의미한다.","eImp":"The regional office represents domestic coastal shipping interests; the new leadership marks a change in the sector's policy channel.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147819"},{"code":"KR","title":"한국선급, 2028년 시행 도선사용 승강장치 규정 지침 발간","src":"코리아쉬핑가제트","date":"2026-08-11","kSum":"도선사용 승강장치(파일럿 사다리) 규정 개정안이 2028년 1월 1일부터 발효될 예정인 가운데, 한국선급(KR)이 이를 대비한 적용 지침을 발간했다. 강화된 IMO/SOLAS 도선사 승하선 안전 요건을 선박·검사원이 준비하도록 돕는다.","eSum":"With revised pilot-transfer (pilot ladder) rules taking effect Jan 1, 2028, Korean Register published guidance to help ships and surveyors meet the tightened IMO/SOLAS pilot-boarding requirements.","kImp":"도선사 승하선 사고는 인명사고 위험이 큰 분야로, 강화 규정 대비 지침은 선사의 조기 준비와 안전관리 강화에 직결된다.","eImp":"Pilot-transfer accidents carry high fatality risk; early guidance drives shipowners' preparation and safety compliance.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147808"},{"code":"KR","title":"영국 해상보험사 UK P&I, 한국 시장 전담 언더라이터 김정숙 선임","src":"코리아쉬핑가제트","date":"2026-08-11","kSum":"영국 해상보험사 UK P&I클럽이 한국 시장을 전담할 김정숙 선임 언더라이터를 선임했다. 한국 선주·운항사 고객 대응을 강화하려는 조치로, 국내 P&I 보험 시장 공략 의지를 드러냈다.","eSum":"The UK P&I Club appointed Kim Jung-sook as senior underwriter dedicated to the Korean market, strengthening its service to Korean shipowners and operators.","kImp":"글로벌 P&I 클럽의 한국 전담 인력 배치는 국내 선주보험 시장의 경쟁 심화와 한국 해운 위상 반영을 보여준다.","eImp":"A dedicated Korea underwriter signals intensifying competition in the domestic P&I market and Korea's rising shipping profile.","url":"https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147820"}]},{"code":"INS","type":"news","kTitle":"Section 12. 선박보험(H&M)","eTitle":"Section 12. Marine Insurance (H&M)","items":[{"code":"INS","title":"Container ship MSC Silvana VIII sinks off Zhoushan after grounding - a major hull total loss","src":"Insurance Marine News","date":"2026-08-11","kSum":"8,401 TEU 컨테이너선 MSC Silvana VIII(실바나 8호)가 수리조선소 출항 직후 좌초·침수 끝에 중국 저우산(Zhoushan) 인근에서 침몰했다. 여러 차례 재부양 시도가 실패했고 태풍 돌핀(Dolphin)이 겹치며 선체 대부분이 수몰됐다. 선체·기관 전손으로 H&M 보험시장에 거액 클레임이 예상된다.","eSum":"The 8,401 TEU boxship MSC Silvana VIII sank near Zhoushan, China after grounding on leaving a repair yard and progressively flooding. Multiple refloating attempts failed and Typhoon Dolphin worsened the casualty. The likely total loss points to a sizeable H&M claim.","kImp":"대형 컨테이너선 전손은 H&M 보험자에게 거액 클레임과 요율 압박으로 이어진다.","eImp":"A large boxship total loss brings a heavy H&M claim and rate pressure.","url":"https://insurancemarinenews.com/insurance-marine-news/container-ship-msc-silvana-viii-imo-9309459-has-sunk-near-daishan-zhoushan-china-after-it-suffered-progressive-flooding-following-a-grounding-days-after-departing-a-ship-repair-yard-on-july-11th/"},{"code":"INS","title":"Accredited selects Hellenic Hull as first dedicated ocean marine MGA partner","src":"Insurance Marine News","date":"2026-08-11","kSum":"Accredited Insurance(Europe)와 Hellenic Hull Management이 선체·기관(H&M) 및 부수 해상위험을 담보하는 위임인수(delegated authority) 파트너십을 체결했다. Hellenic Hull은 Accredited의 첫 전용 오션 마린 MGA 파트너가 됐다. 전문 헐 언더라이팅 역량을 프론팅 캐패시티와 결합하는 구조다.","eSum":"Accredited Insurance (Europe) and Hellenic Hull Management have entered a delegated authority partnership covering Hull & Machinery and ancillary marine risks. Hellenic Hull becomes Accredited's first dedicated ocean marine MGA partner. It pairs specialist hull underwriting with fronting capacity.","kImp":"전문 헐 MGA 모델 확산은 H&M 인수 캐패시티 공급 구조 변화를 시사한다.","eImp":"Growth of specialist hull MGAs signals shifting H&M capacity supply.","url":"https://insurancemarinenews.com/keep/accredited-selects-hellenic-hull-as-first-dedicated-ocean-marine-mga-partner/"},{"code":"INS","title":"AXA XL Re appoints two senior underwriters to Marine & Energy team","src":"Insurance Marine News","date":"2026-08-11","kSum":"AXA XL Reinsurance가 Stephen Barnard와 Callum Higgins를 해상·에너지(Marine & Energy) 부문 시니어 언더라이터로 선임했다. 재보험 해상 인수 역량을 강화하려는 조치다. H&M을 포함한 마린 재보험 시장의 인수 경쟁이 이어지고 있다.","eSum":"AXA XL Reinsurance has appointed Stephen Barnard and Callum Higgins as Senior Underwriters in its Marine & Energy team. The move strengthens its marine reinsurance underwriting bench. It reflects continued competition in marine (including H&M) reinsurance.","kImp":"마린 재보험 인수 인력 보강은 H&M 캐패시티 경쟁 심화를 반영한다.","eImp":"Bolstering marine reinsurance underwriting reflects intensifying H&M capacity competition.","url":"https://insurancemarinenews.com/insurance-marine-news/axa-xl-re-appoints-two-senior-underwriters-to-marine-energy-team/"},{"code":"INS","title":"Sompo moves to close GPS jamming insurance gap","src":"Insurance Marine News","date":"2026-08-10","kSum":"일본 Sompo Japan이 선박 항법장비에 대한 전파 교란(GPS 재밍)으로 인한 경제적 손실을 겨냥한 업계 최초의 보험을 출시했다. 지정학적 리스크로 커지는 항법 간섭 노출을 담보하려는 상품이다. 헐·전쟁위험 인접 영역의 신규 담보로 주목된다.","eSum":"Japan's Sompo Japan has launched what it calls the shipping industry's first cover specifically targeting economic losses from radio interference (GPS jamming) with ship navigation. The product responds to growing navigational-interference exposure driven by geopolitical risk. It is a notable new cover adjacent to hull and war risk.","kImp":"재밍 담보 신설은 헐·전쟁위험 인수의 신흥 리스크 대응을 보여준다.","eImp":"A jamming cover shows hull and war underwriting adapting to emerging risks.","url":"https://insurancemarinenews.com/insurance-marine-news/sompo-moves-to-close-gps-jamming-insurance-gap/"},{"code":"INS","title":"Iran claims strikes on two tankers in Strait of Hormuz","src":"Insurance Marine News","date":"2026-08-10","kSum":"이란이 8월 8일 호르무즈 해협에서 적대 표적 2척을 타격했다고 주장했으며, 대상은 원유탱커 Nissos Kea 등으로 추정된다(미확인 보도). 걸프 해역 전쟁위험이 재차 고조되며 헐 전쟁위험 요율에 압박이 되고 있다. 선주들은 추가보험료(AP)와 항로 리스크를 재점검하고 있다.","eSum":"Iran claimed it struck two hostile targets in the Strait of Hormuz on 8 August, reportedly including the crude tanker Nissos Kea (unconfirmed). The renewed Gulf war-risk escalation pressures hull war-risk rates. Owners are reassessing additional premiums and routing risk.","kImp":"걸프 긴장 재고조는 헐 전쟁위험 요율·추가보험료 인상 요인이다.","eImp":"Renewed Gulf tension drives up hull war-risk rates and additional premiums.","url":"https://insurancemarinenews.com/insurance-marine-news/iran-claims-strikes-on-two-vessels/"},{"code":"INS","title":"Resolve Marine advances next stage of MSC Baltic III wreck removal","src":"Insurance Marine News","date":"2026-08-10","kSum":"뉴펀들랜드 해안에서 Resolve Marine이 좌초선 MSC Baltic III 잔해 이동을 위한 300톤급 체인풀러 12기 설치를 마무리하고 있다. 대형 난파선 제거는 헐 전손 및 난파물 제거(WRC) 비용에 직결된다. 복잡한 살베지 작업이 계속되고 있다.","eSum":"Off Newfoundland, Resolve Marine is finishing installation of twelve 300-tonne chain pullers to move the grounded MSC Baltic III wreck. Major wreck removal bears directly on hull total-loss and wreck-removal costs. The complex salvage continues.","kImp":"대형 난파선 제거 장기화는 헐 전손·난파물 제거 비용 부담을 키운다.","eImp":"Prolonged wreck removal raises hull total-loss and wreck-removal costs.","url":"https://insurancemarinenews.com/insurance-marine-news/resolve-marine-is-completing-next-stage-of-msc-baltic-iii-salvage/"},{"code":"INS","title":"Sean M Dalton nominated to be next IUMI President","src":"Insurance Marine News","date":"2026-08-06","kSum":"국제해상보험연맹(IUMI) 지명위원회가 차기 회장으로 Sean M Dalton을 지명했다. IUMI는 헐·화물 등 글로벌 해상보험 인수 동향과 통계를 주도하는 기구다. 신임 회장 체제에서 헐 시장 규율 강화 논의가 이어질 전망이다.","eSum":"The Nominating Committee of the International Union of Marine Insurance (IUMI) has nominated Sean M Dalton as its next President. IUMI leads global marine (including hull) underwriting analysis and statistics. Discussion on hull-market discipline is likely to continue under new leadership.","kImp":"IUMI 신임 회장 지명은 헐 시장 규율·통계 어젠다의 연속성을 가늠케 한다.","eImp":"The new IUMI president signals continuity on hull-market discipline and data.","url":"https://insurancemarinenews.com/insurance-marine-news/sean-m-dalton-is-nominated-to-be-next-iumi-president/"},{"code":"INS","title":"HFW appoints new Partner in Singapore","src":"Insurance Marine News","date":"2026-08-05","kSum":"글로벌 로펌 HFW가 Peter Glover를 싱가포르 파트너로 선임하며 아시아·태평양 사업을 확장했다. HFW는 헐 클레임·해상보험 분쟁 자문에서 활동하는 주요 로펌이다. 아·태 해상보험 분쟁 수요 증가에 대응한 인선이다.","eSum":"Global law firm HFW has appointed Peter Glover as a Partner in Singapore, growing its Asia-Pacific practice. HFW is a leading firm in hull claims and marine insurance disputes. The hire responds to rising APAC marine-insurance dispute demand.","kImp":"아·태 헐·해상보험 분쟁 자문 수요 확대를 반영한 인선이다.","eImp":"Reflects growing APAC demand for hull and marine-insurance dispute advice.","url":"https://insurancemarinenews.com/insurance-marine-news/hfw-appoints-new-partner-in-singapore/"},{"code":"INS","title":"Christian Daniel Ouegnin named Managing Director of Filhet-Allard Africa","src":"Insurance Marine News","date":"2026-08-05","kSum":"코트디부아르 아비장 소재 해상보험 브로커 Filhet-Allard Africa가 Christian Daniel Ouegnin(크리스티앙 다니엘 우에냉)을 대표이사(MD)로 선임했다. 이 브로커는 그룹의 범아프리카 해상보험 사업을 담당한다. 아프리카 헐·해상보험 중개시장 확장 흐름을 보여준다.","eSum":"Abidjan-based marine insurance broker Filhet-Allard Africa has named Christian Daniel Ouegnin as Managing Director. The brokerage runs the group's pan-African marine insurance business. It illustrates expansion in Africa's hull and marine broking market.","kImp":"아프리카 해상보험 중개 확장은 헐 캐패시티 접근성 확대를 시사한다.","eImp":"African marine broking expansion signals wider access to hull capacity.","url":"https://insurancemarinenews.com/insurance-marine-news/christian-daniel-ouegnin-named-as-managing-director-of-filhet-allard-africa/"}]},{"code":"PNI","type":"news","kTitle":"Section 13. P&I 클럽","eTitle":"Section 13. P&I Clubs","items":[{"code":"PNI","title":"Japan P&I Club reports gross tonnage of 81.9m gt in annual report","src":"Insurance Marine News","date":"2026-08-11","kSum":"일본 P&I 클럽(Japan Club)이 2025/26 연차보고서에서 2025 정책연도 중 외항선주 부문 신규 가입 530만 gt를 확보했다고 밝혔다. 총 등록톤수는 8,190만 gt로 집계됐다. 국제그룹(IG) 클럽으로서 견조한 톤수 기반을 유지하고 있다.","eSum":"The Japan P&I Club said in its 2025/26 annual report that it took on 5.3m gt of new entries for ocean-going owners during the 2025 policy year. Total entered tonnage stood at 81.9m gt. As an International Group club it maintains a solid tonnage base.","kImp":"톤수 성장은 IG 클럽의 상호주의 기반 안정성을 보여준다.","eImp":"Tonnage growth underlines the stability of the club's mutual base.","url":"https://insurancemarinenews.com/insurance-marine-news/japan-club-reports-gross-tonnage-of-81-9m-in-annual-report/"},{"code":"PNI","title":"UK P&I Club appoints Jeong-Sook Kim as Senior Underwriting Director, South Korea","src":"Insurance Marine News","date":"2026-08-11","kSum":"UK P&I 클럽이 정숙 김(Jeong-Sook Kim)을 시니어 언더라이팅 디렉터로 선임해 한국 시장을 담당하게 했다. 런던 본사에 기반을 두고 한국 회원사 인수 업무를 총괄한다. 아시아 핵심 시장에 대한 인수 역량 강화 조치다.","eSum":"The UK P&I Club has appointed Jeong-Sook Kim as Senior Underwriting Director with initial responsibility for the Korean market. Based in the London office, she will lead underwriting for Korean members. The move strengthens capability in a key Asian market.","kImp":"한국 전담 인수 임원 선임은 아시아 P&I 회원 기반 강화를 노린다.","eImp":"A Korea-focused underwriting hire targets a stronger Asian P&I book.","url":"https://insurancemarinenews.com/insurance-marine-news/uk-club-appoints-jeong-sook-kim-as-senior-underwriting-director-south-korea/"},{"code":"PNI","title":"West cites strong financial performance in full 2025/26 report","src":"Insurance Marine News","date":"2026-08-07","kSum":"국제그룹 클럽 West(구 West of England)가 2025/26 전체 재무보고서에서 최근 풀(Pool) 실적과 다각화 모델이 견조한 재무성과를 뒷받침했다고 밝혔다. 상호 P&I 클럽으로서 자본과 준비금 기반이 강화됐다. 풀 참여 실적이 전반 성과에 긍정적으로 작용했다.","eSum":"International Group club West (formerly West of England) said in its full 2025/26 report that recent Pool performance and its diversified model supported a strong financial result. As a mutual P&I club its capital and reserves base has strengthened. Pool participation contributed positively to overall performance.","kImp":"견조한 실적은 클럽의 자본여력과 요율 안정에 우호적이다.","eImp":"A strong result supports the club's capital strength and rate stability.","url":"https://insurancemarinenews.com/insurance-marine-news/wests-full-report-for-2025-26-cites-strong-financial-performance/"}]},{"code":"VET","type":"news","kTitle":"Section 14. 선박심사(Vetting)","eTitle":"Section 14. Vetting","items":[{"code":"VET","title":"IMO expands global PSC data exchange with Black Sea, Caribbean MoUs","src":"SAFETY4SEA","date":"2026-08-05","kSum":"국제해사기구(IMO)가 흑해 양해각서(Black Sea MoU) 및 카리브해 양해각서(Caribbean MoU)와 항만국통제(PSC) 선박검사 정보 교환을 강화하는 갱신 협정에 서명했다. 이로써 IMO는 8개 지역 PSC 체제와 데이터 교환 협정을 체결했으며, GISIS 내 PSC 모듈과 통합 데이터베이스(ODB) 구축을 뒷받침한다. 지역 간 검사 데이터 공유로 보다 조화롭고 효율적인 표적 검사가 가능해질 전망이다.","eSum":"The IMO signed updated data-exchange agreements with the Black Sea and Caribbean MoUs on Port State Control, strengthening the global exchange of ship inspection information. With these, the IMO has now concluded such agreements with eight regional PSC regimes, supporting the PSC module in GISIS and the development of an Overarching Database (ODB). The aim is more harmonised, data-driven inspection targeting across regions.","kImp":"전 세계 PSC 검사 데이터 통합으로 표적 선박 선별 정확도가 높아진다.","eImp":"Integrating global PSC inspection data sharpens targeting of substandard ships.","url":"https://safety4sea.com/imo-expands-global-psc-data-exchange-with-black-sea-caribbean-mous/"}]},{"code":"CLASS","type":"news","kTitle":"Section 15. 선급","eTitle":"Section 15. Classification","items":[{"code":"CLASS","title":"LR launches industry-first framework for digital 3D model class approval","src":"Lloyd's Register","date":"2026-08-11","kSum":"로이드선급(LR)이 선급 승인 과정에서 지능형 3D 모델을 사용하기 위한 업계 최초의 가이던스(LR-GN-066)를 발간했다. 조선소·설계사가 기존 2D 도면 대신 3D 모델로 구조 도면 승인을 진행할 수 있는 실무 프레임워크를 제시한다. 파일 포맷·메타데이터·개정관리 등 요건을 규정해 디지털 우선 설계·심사로의 전환을 지원한다.","eSum":"Lloyd's Register (LR) has published what it calls the industry's first guidance (LR-GN-066) for using intelligent 3D models in class approval. It gives shipyards and designers a practical framework to use 3D models in lieu of traditional 2D plans for structural plan approval. By defining file formats, metadata and revision control it supports a shift to digital-first design and review.","kImp":"3D 모델 선급 승인 표준화는 디지털 클래스 전환을 가속한다.","eImp":"Standardising 3D-model approval accelerates the move to digital class.","url":"https://www.lr.org/en/knowledge/press-room/press-listing/press-release/2026/lloyds-register-launches-industry-first-framework-for-digital-3d-model-approval/"},{"code":"CLASS","title":"LR strengthens offshore energy capability with senior APAC appointment","src":"Lloyd's Register","date":"2026-08-10","kSum":"로이드선급(LR)이 Wouter Pattynama를 오프쇼어 담당 이그제큐티브 클라이언트 솔루션 매니저로 선임해 호주·뉴질랜드 및 아·태 지역 오프쇼어 에너지 역량을 강화했다. 그는 호주 오프쇼어 규제기관(NOPSEMA) 출신으로 약 30년 경력을 보유했다. 노후 자산·디지털 전환·탈탄소 과제 대응 자문을 제공한다.","eSum":"Lloyd's Register (LR) appointed Wouter Pattynama as Executive Client Solutions Manager, Offshore, strengthening offshore energy capability across Australia, New Zealand and wider APAC. He joins from Australia's offshore regulator NOPSEMA with nearly 30 years' experience. He will advise on ageing assets, digital transformation and decarbonisation.","kImp":"선급의 오프쇼어·아·태 역량 강화는 에너지 전환 자산 감리 수요를 반영한다.","eImp":"Bolstering offshore APAC capability reflects demand for energy-transition asset assurance.","url":"https://www.lr.org/en/knowledge/insights-articles/lr-strengthens-offshore-energy-capabilities-with-senior-apac-appointment/"},{"code":"CLASS","title":"Korean Register certifies 3D printing technology for shipbuilding and defence","src":"Korean Register","date":"2026-08-10","kSum":"한국선급(KR, Korean Register)이 3D 프린팅(적층제조) 기술을 인증해 신규 부품 제작을 넘어 방산·조선 분야의 유지보수·수리(MRO)까지 적용을 확대했다. 선급 인증을 통해 적층제조 부품의 신뢰성·품질을 담보한다. 디지털·첨단 제조 기반의 선급 서비스 확장 사례다.","eSum":"Korean Register (KR) has certified 3D printing (additive manufacturing) technology, expanding applications from new part production to maintenance and repair in defence and shipbuilding. The class certification assures the reliability and quality of additively manufactured parts. It marks KR's expansion of class services around advanced digital manufacturing.","kImp":"적층제조 부품 선급 인증은 선용품 공급망·MRO 혁신을 뒷받침한다.","eImp":"Class certification of additive parts supports supply-chain and MRO innovation.","url":"https://www.krs.co.kr/eng/BBS/BF_Main.aspx?MRID=558"}]},{"code":"COMM","type":"news","kTitle":"Section 16. 상업/시장","eTitle":"Section 16. Commercial & Markets","items":[{"code":"COMM","title":"Minsheng expands Shell-backed MR tanker programme to 11 newbuilds","src":"Splash247","date":"2026-08-10","kSum":"민성금융리스(Minsheng Financial Leasing)가 광저우조선국제(GSI)에서 진행 중인 쉘(Shell) 지원 MR 탱커 프로그램을 기존 6척에서 11척으로 확대했다. 49,900 DWT급 케미컬·석유제품운반선으로 GSI 16세대 MR 설계를 채택해 연료소모와 배출을 줄였으며, 11척 전량은 쉘탱커스(Shell Tankers)에 장기 용선된다.","eSum":"Minsheng Financial Leasing has expanded its Shell-backed tanker programme at Guangzhou Shipyard International to 11 ships, adding five newbuildings as the original six-vessel series enters construction. The 49,900 dwt chemical and product carriers use GSI's 16th-generation MR design with an optimised hull to cut fuel use and emissions. All 11 will be chartered to Shell Tankers under pre-agreed terms.","kImp":"MR 제품선 신조 발주가 이어지며 정유 메이저의 선대 통제와 중국 리스사의 자금 조달 역할이 강화되고 있다.","eImp":"Continued MR newbuild ordering shows oil majors locking in tonnage via Chinese lessor financing.","url":"https://splash247.com/minsheng-expands-shell-backed-mr-tanker-programme-to-11-newbuilds/"},{"code":"COMM","title":"Procopiou's Hengli VLCC haul reaches 20","src":"Splash247","date":"2026-08-11","kSum":"조지 프로코피우(George Procopiou)의 다이나콤(Dynacom)이 헝리중공업(Hengli Heavy Industries)에 VLCC를 추가 발주하며 해당 조선소 내 초대형 원유운반선 발주 잔량을 20척으로 늘렸다. 사상 최대 규모의 원유선 발주 붐 속에서 그리스 선주의 공격적 신조 확장세를 보여준다.","eSum":"George Procopiou's Dynacom has added further VLCCs at Hengli Heavy Industries, taking its orderbook at the Chinese yard to 20 vessels. The move reflects aggressive Greek-owner fleet expansion amid a record crude tanker newbuilding boom.","kImp":"2026년 사상 최대의 VLCC 발주 랠리 속에서 대형 선주들의 선대 선점 경쟁이 가열되고 있다.","eImp":"Owners are racing to secure tonnage in 2026's record VLCC ordering rally.","url":"https://splash247.com/procopious-hengli-vlcc-haul-reaches-20/"},{"code":"COMM","title":"US sends seized shadow fleet tankers for scrap","src":"Splash247","date":"2026-08-11","kSum":"미국이 제재 회피 원유 거래에 연루돼 나포한 노후 탱커들을 재순환 대신 해체로 돌리기 시작했다. 선박 해체 대기업 GMS가 미 재무부로부터 나포·제재 선박 매입·해체 라이선스를 확보했으며, GMS는 실효적 라이선스 체계가 갖춰지면 연간 100척 이상의 그림자 선대를 시장에서 제거할 수 있다고 추정한다.","eSum":"The US has begun channelling ageing tankers seized in its sanctions campaign toward demolition rather than letting them re-enter circulation. Recycling group GMS has secured US Treasury licences to buy and scrap seized and sanctioned ships, and estimates it could remove more than 100 shadow vessels a year under a workable regime.","kImp":"그림자 선대 축소는 노후 탱커 공급 감소로 이어져 정상 탱커 시장 수급과 선가에 우호적으로 작용할 수 있다.","eImp":"Scrapping shadow tonnage trims aged supply, a potential support for mainstream tanker values.","url":"https://splash247.com/us-sends-seized-shadow-fleet-tankers-for-scrap/"},{"code":"COMM","title":"d'Amico reclaims MR from lease for $15m","src":"Splash247","date":"2026-08-11","kSum":"이탈리아 선주 다미코(d'Amico International Shipping)가 리스로 운용하던 MR 제품선 1척을 1,500만 달러에 되사들여 자기 소유로 전환했다. 견조한 제품선 시장과 자산가치를 배경으로 세일앤리스백 자산을 회수하는 선주들의 움직임을 보여준다.","eSum":"Italian owner d'Amico International Shipping has bought back an MR product tanker it held on lease for $15m, converting it to owned tonnage. The move reflects owners reclaiming sale-and-leaseback assets against a firm product tanker market and asset values.","kImp":"제품선 자산가치 상승 국면에서 선주들의 리스 회수·자기소유 전환이 활발하다.","eImp":"Firm product-tanker values are prompting owners to reclaim leased assets.","url":"https://splash247.com/damico-reclaims-mr-from-lease-for-15m/"},{"code":"COMM","title":"China's coal buildout offers fresh ballast for dry bulk","src":"Splash247","date":"2026-08-10","kSum":"중국이 2026년 상반기에 전년 대비 43% 늘어난 30GW 규모의 신규 석탄화력을 준공하고 주요 발전소 석탄 소비도 올해 최고치를 경신하면서 벌크 수요의 버팀목이 되고 있다. 다만 몽골·러시아산 석탄의 철도 수송 확대는 케이프사이즈 해상 물동량을 일부 잠식할 수 있다는 상반된 신호도 있다.","eSum":"China commissioned 30 GW of new coal power in the first half of 2026, up 43% year on year, while thermal coal burn at major plants hit fresh highs, underpinning dry bulk demand. Analysts remain bullish on near-term imports, though expanding Mongolian and Russian coal by rail could erode some capesize seaborne volumes.","kImp":"석탄 수요가 에너지 안보 자산으로 재평가되며 벌크선 수급의 핵심 변수로 작용하고 있다.","eImp":"Coal, reframed as an energy-security asset, remains a key swing factor for bulker demand.","url":"https://splash247.com/chinas-coal-buildout-offers-fresh-ballast-for-dry-bulk/"},{"code":"COMM","title":"Star Bulk walks away from Genco fleet deal","src":"Splash247","date":"2026-08-11","kSum":"스타벌크(Star Bulk Carriers)가 디아나쉬핑(Diana Shipping)으로부터 젠코(Genco)의 벌크선 16척을 4억7,050만 달러에 인수하려던 계약을 철회했다. 뉴캐슬막스 1척, 케이프사이즈 6척, 울트라막스 7척, 수프라막스 2척(총 약 180만 DWT) 규모로, 디아나의 젠코 인수 지연이 배경이다.","eSum":"Star Bulk Carriers has pulled out of a $470.5m deal to acquire 16 Genco bulkers from Diana Shipping, removing a key component of Diana's takeover attempt. The package covered one newcastlemax, six capesizes, seven ultramaxes and two supramaxes totalling about 1.8m dwt. Star Bulk cited the lack of progress between Diana and Genco.","kImp":"대형 벌크선 M&A·선대 재편 향방이 드라이벌크 시장 심리에 영향을 준다.","eImp":"Shifting bulker M&A dynamics weigh on dry bulk sentiment.","url":"https://splash247.com/star-bulk-walks-away-from-genco-fleet-deal/"},{"code":"COMM","title":"Uni-Asia doubles up on Japanese handysize newbuilds","src":"Splash247","date":"2026-08-10","kSum":"우니아시아그룹(Uni-Asia Group)이 일본에서 40,000 DWT급 핸디사이즈 벌커를 추가 발주하며 신조 프로그램을 2척으로 늘렸다. 니혼조선(Nihon Shipyard) 계약으로 이마바리조선(Imabari Shipbuilding)이 건조하며, 연료효율 엔진과 이중연료 대응 설계로 향후 개조가 가능하다. 인도는 2029년 4분기~2030년 상반기로 예정됐다.","eSum":"Uni-Asia Group has doubled its Japanese handysize newbuilding programme with a second 40,000 dwt bulker, to be built by Imabari Shipbuilding via Nihon Shipyard. The ship features a fuel-efficient engine and dual-fuel-ready design allowing a future retrofit, with delivery slated for Q4 2029 to H1 2030.","kImp":"소형 벌커 선대 교체가 이어지며 연료효율·이중연료 대응 설계가 신조의 기본 사양으로 자리잡고 있다.","eImp":"Fleet renewal in smaller bulkers is normalising fuel-efficient, dual-fuel-ready designs.","url":"https://splash247.com/uni-asia-doubles-up-on-japanese-handysize-newbuilds/"},{"code":"COMM","title":"Splash Singapore: Western Bulk's Torbjorn Gjervik on the search for new ideas","src":"Splash247","date":"2026-08-11","kSum":"웨스턴벌크(Western Bulk)의 토르비외른 예르비크(Torbjorn Gjervik)가 스플래시 싱가포르 인터뷰에서 변동성이 큰 드라이벌크 시장에서 오퍼레이터가 살아남기 위한 차별화와 새로운 아이디어의 필요성을 강조했다. 트레이딩 중심 오퍼레이터의 리스크 관리와 수익 창출 전략을 조명한다.","eSum":"Western Bulk's Torbjorn Gjervik, speaking at Splash Singapore, stressed the need for differentiation and fresh ideas for operators to thrive in a volatile dry bulk market. The interview highlights how a trading-focused operator approaches risk management and margin generation.","kImp":"오퍼레이터 관점의 시장 진단은 드라이벌크 사이클과 리스크 관리 트렌드를 가늠하는 지표가 된다.","eImp":"An operator's read offers a gauge on the dry bulk cycle and risk-management trends.","url":"https://splash247.com/splash-singapore-western-bulks-torbjorn-gjervik-on-the-search-for-new-ideas/"},{"code":"COMM","title":"Grimaldi takes delivery of first new-series 220m PCTC 'Grande Pacifico'","src":"MarineLink","date":"2026-08-11","kSum":"[자동차운반선 시장] 그리말디(Grimaldi)가 13번째 암모니아-레디 자동차운반선이자 신규 시리즈 첫 선박 '그란데 파시피코(Grande Pacifico)'를 인도받았다. 차이나머천츠중공업 장쑤 건조, RINA 선급의 전장 220m 선박으로 5척 자매선 중 선두이며, 적재량 확대와 에너지효율을 동시에 겨냥했다.","eSum":"[Car-carrier market] Grimaldi has taken delivery of Grande Pacifico, its 13th ammonia-ready PCTC and the first of a new five-ship series built by China Merchants Heavy Industries Jiangsu and classed by RINA. The 220m vessel targets higher capacity alongside strong energy efficiency.","kImp":"PCTC 선복 부족 국면에서 대형 신조 인도가 이어지며 자동차운반 시장 선대가 확장되고 있다.","eImp":"Ongoing large PCTC deliveries expand car-carrier capacity amid a tight market.","url":"https://www.marinelink.com/news/grimaldi-takes-delivery-first-newseries-542013"},{"code":"COMM","title":"Shanwei accelerates port build for BYD car-export push","src":"Splash247","date":"2026-08-11","kSum":"[자동차운반선 시장] 중국 산웨이(Shanwei)항이 비야디(BYD)의 완성차 수출 급증을 뒷받침할 전용 터미널 건설에 속도를 내고 있다. 중국 OEM의 수출 확대가 PCTC 물동량과 장기 용선 수요, 항만 투자를 함께 끌어올리는 구조를 보여준다.","eSum":"[Car-carrier market] China's Shanwei port is fast-tracking dedicated terminal capacity to support surging BYD vehicle exports. The build reflects how Chinese OEM export growth is lifting PCTC volumes, long-term charter demand and port investment together.","kImp":"중국 자동차 수출 붐이 PCTC 용선료·물동량의 구조적 강세를 뒷받침한다.","eImp":"China's auto-export boom underpins structurally firm PCTC volumes and charter rates.","url":"https://splash247.com/shanwei-accelerates-port-build-for-byd-export-push/"},{"code":"COMM","title":"Fire on COSCO car carrier off Costa Rica tightens PCTC supply picture","src":"Baird Maritime","date":"2026-08-10","kSum":"[자동차운반선 시장] 코스코쉬핑특수운수(COSCO Shipping Specialized Carriers)의 자동차운반선 '민장커우(Min Jiang Kou)'에서 코스타리카 인근 해상 화재가 발생해 전원 구조됐다. 이미 빠듯한 PCTC 선복 상황에서 선박 casualty는 가용 선복을 추가로 압박할 수 있어 시장이 주시하고 있다.","eSum":"[Car-carrier market] A fire aboard COSCO Shipping Specialized Carriers' PCTC Min Jiang Kou off Costa Rica saw all crew rescued. With PCTC tonnage already tight, vessel casualties can further squeeze available capacity, a factor the market is watching.","kImp":"선박 사고로 인한 선복 이탈 가능성은 이미 타이트한 PCTC 용선 시장에 상방 요인이다.","eImp":"Casualty-driven capacity loss is an upside risk for an already-tight PCTC charter market.","url":"https://www.bairdmaritime.com/security/incidents/accidents/fire-ignites-on-car-carrier-off-costa-rica-all-on-board-rescued"}]},{"code":"GEO","type":"news","kTitle":"Section 17. 지정학","eTitle":"Section 17. Geopolitics","items":[{"code":"GEO","title":"파나마운하 대기 1주일 넘자…컨테이너선, 순번 앞당기려 400만달러 지불","src":"gCaptain","date":"2026-08-11","kSum":"파나마운하 통항 대기시간이 1주일을 넘어서자 컨테이너선 시스팬 베네팩터호 선주가 경매에서 거의 사상 최고 수준인 400만달러를 지불하고 우선 통항권을 확보했다. 가뭄·혼잡으로 예약 슬롯 경매가가 급등하고 있다.","eSum":"With Panama Canal waits exceeding a week, the owner of the containership Seaspan Benefactor paid a near-record $4 million at auction to jump the queue, as drought and congestion drive slot prices sharply higher.","kImp":"파나마운하 병목은 아시아-미 동안 정기선·에너지 화물 운임과 스케줄에 직접 타격을 주며, 통항 비용 급등은 글로벌 공급망 비용 상승으로 이어진다.","eImp":"Panama Canal bottlenecks directly hit Asia-US East Coast liner and energy freight costs and schedules, raising global supply-chain expenses.","url":"https://gcaptain.com/ship-pays-4-million-to-cut-the-line-at-panama-canal/"},{"code":"GEO","title":"美, 이란·베네수엘라 원유 실은 그림자함대 탱커 선장에 징역 10개월…해안경비대 추격 끝 검거","src":"gCaptain","date":"2026-08-10","kSum":"이란·베네수엘라산 원유 수송과 연계된 그림자함대(제재 회피) 탱커의 전 선장이 대서양을 가로지른 수 주간의 미 해안경비대 추격에서 정지 명령을 거부한 혐의로 연방 교도소 10개월형을 선고받았다.","eSum":"The former master of a shadow-fleet tanker linked to Iranian and Venezuelan oil was sentenced to 10 months in US federal prison for refusing to stop during a weeks-long Coast Guard pursuit across the Atlantic.","kImp":"제재 회피 그림자함대에 대한 미국의 형사 처벌 강화는 불법 원유 물류망에 압박을 가하지만, 노후 선박 운항으로 인한 안전·환경 리스크는 여전하다.","eImp":"Tougher US criminal enforcement pressures sanctions-evading shadow fleets, though aging-vessel safety and environmental risks persist.","url":"https://gcaptain.com/shadow-fleet-tanker-captain-sentenced-to-10-months-after-weeks-long-coast-guard-chase/"},{"code":"GEO","title":"한화, 美 오스탈USA에 12억달러 인수 예비 제안…美 조선업 확대 정책과 맞물려","src":"gCaptain","date":"2026-08-10","kSum":"한국 한화가 미국 최대 해군 조선사 중 하나인 오스탈USA를 최대 12억달러에 인수하는 예비 제안을 내놨다. 성사되면 워싱턴의 국내 조선 역량 확충 정책 흐름 속에 한화가 미 함정 건조 거점을 확보하게 된다.","eSum":"South Korea's Hanwha made a preliminary offer of up to $1.2 billion for Austal USA, one of the largest US naval shipbuilders, as Washington pushes to expand domestic shipbuilding capacity.","kImp":"한화의 오스탈 인수 시도는 한미 조선동맹과 미 해군 함정 공급망 재편의 핵심 사례로, 한국 방산·조선의 미국 시장 진출 확대를 상징한다.","eImp":"Hanwha's Austal bid is a landmark in US-Korea shipbuilding alignment and US naval supply-chain restructuring.","url":"https://gcaptain.com/hanwha-makes-1-2-billion-bid-for-austal-usa/"},{"code":"GEO","title":"백악관, 존스법 면제 90일 추가 연장…역사상 최장 유예에 새 제한 부과","src":"gCaptain","date":"2026-08-10","kSum":"트럼프 대통령이 외국적 선박의 미국 항간 원유·상품 운송을 허용하는 존스법 면제를 90일 추가 연장했다. 다만 조선업계와 의회의 반발에 따라 새로운 제한을 부과했으며, 이는 존스법 역사상 최장기간 유예다.","eSum":"President Trump extended for 90 days a Jones Act waiver letting foreign-flagged ships move oil and commodities between US ports, but added new limits after shipbuilders and Congress objected — the longest suspension in the law's history.","kImp":"존스법 면제 연장은 미국 내 에너지 물류비를 낮추지만 자국 조선·해운 보호정책과 충돌해, 미 해운산업 재건 논쟁의 핵심 쟁점이 되고 있다.","eImp":"Extending the waiver eases US energy logistics costs but clashes with domestic shipbuilding protection, a flashpoint in US maritime-revival debate.","url":"https://gcaptain.com/white-house-extends-jones-act-waiver-in-longest-suspension-in-laws-history/"},{"code":"GEO","title":"흑해 곡물 수출 이중고…다뉴브강 사상 최저 수위에 러시아의 오데사 공습까지","src":"gCaptain","date":"2026-08-10","kSum":"다뉴브강 수위가 사상 최저로 떨어지며 루마니아 경유 곡물 수송이 제약받는 가운데, 러시아의 공습 강화로 우크라이나 곡물이 오데사 등 주요 항만에서 우회되면서 흑해 곡물 수출이 새로운 제약에 직면했다.","eSum":"Black Sea grain exports face fresh constraints as record-low Danube levels restrict Romanian routes while escalating Russian strikes divert Ukrainian grain from Odesa and other ports.","kImp":"흑해 곡물 회랑의 물리적·군사적 이중 제약은 세계 식량 공급망과 곡물 운임에 압력을 가하며, 벌크선 시장 변동성을 키운다.","eImp":"Combined physical and military constraints on the Black Sea grain corridor pressure global food supply and bulk freight rates.","url":"https://gcaptain.com/black-sea-grain-exports-squeezed-as-danube-hits-record-low-levels/"},{"code":"GEO","title":"오만 앞바다 제재 대상 그림자함대 탱커서 대규모 기름 유출…약 400㎢로 확산","src":"gCaptain","date":"2026-08-10","kSum":"러시아산 원유를 싣고 제재 대상에 오른 탱커가 오만 자연보호구역 인근에 좌초해 손상되면서, 유출된 원유가 약 400㎢(150제곱마일)에 이르는 대규모 유막을 형성했다고 오만 정부가 밝혔다.","eSum":"A sanctioned tanker carrying Russian crude grounded near an Omani nature reserve and leaked oil, creating a slick covering nearly 400 square km, Oman's government said.","kImp":"제재 회피 노후 그림자함대의 사고는 해양 환경 재난과 함께, 이 선단이 초래하는 안전·보험·책임 공백 문제를 부각한다.","eImp":"The accident highlights environmental disaster risk and the safety, insurance and liability gaps created by aging shadow-fleet tankers.","url":"https://gcaptain.com/oil-spill-off-oman-from-tanker-under-sanctions-against-russia-spreads-over-huge-area/"},{"code":"GEO","title":"머스크·하파크로이트, 홍해 복귀 확대…사우디 제다 기항 추가에도 후티 위협 상존","src":"gCaptain","date":"2026-08-10","kSum":"머스크와 하파크로이트가 홍해·수에즈운하 재이용을 확대하며 아시아-지중해 AE15 서비스에 사우디 제다 기항을 추가했다. 다만 사우디와 예멘 후티 간 교전 재발로 역내 불확실성이 여전하다.","eSum":"Maersk and Hapag-Lloyd are expanding their renewed use of the Red Sea and Suez Canal, adding a Jeddah call on their AE15 Asia-Med service, even as renewed Saudi-Houthi fighting adds regional uncertainty.","kImp":"대형 얼라이언스의 홍해 복귀 확대는 수에즈 정상화 기대를 키우지만, 후티 위협 지속으로 완전 정상화까지는 리스크가 남아 있다.","eImp":"Major carriers' Red Sea return signals hope for Suez normalization, but persistent Houthi threats keep full recovery uncertain.","url":"https://gcaptain.com/maersk-and-hapag-lloyd-expand-red-sea-return-with-new-jeddah-call/"},{"code":"GEO","title":"중국 선사들, 북극항로 최대 성수기 채비…최소 6개사 컨테이너·벌크선 투입","src":"gCaptain","date":"2026-08-10","kSum":"중국 해운사들이 북극 북동항로(NSR)에서 사상 최대 성수기를 준비하고 있다. 최소 6개 선사가 중국과 러시아, 나아가 서유럽 주요 항만을 잇는 컨테이너·벌크 항해를 계획했으며, 초기 컨테이너 서비스만 약 2만TEU 규모다.","eSum":"Chinese shipping firms are preparing their busiest Northern Sea Route season yet, with at least six operators planning container and bulk voyages linking China with Russia and Western Europe — initial container services alone near 20,000 TEU.","kImp":"중국-러시아 주도의 북극항로 확대는 수에즈·홍해 우회 대안이자 지정학적 블록화 흐름을 반영하며, 서방 제재·환경 논란과 맞물려 있다.","eImp":"China-Russia-led Arctic route growth offers a Suez/Red Sea alternative and reflects geopolitical bloc-building amid sanctions and environmental scrutiny.","url":"https://gcaptain.com/chinese-operators-gear-up-for-busy-arctic-shipping-season/"},{"code":"GEO","title":"터키, 지연 끝에 흑해행 해협 통항 재개…역내 보안 위험 고조","src":"gCaptain","date":"2026-08-09","kSum":"터키가 일부 선박에 대한 원인 불명의 지연 조치 이후 흑해로 향하는 해협(보스포루스·다르다넬스) 통항을 재개했다. 역내 보안 위험이 고조되는 가운데 이뤄진 조치다.","eSum":"Turkey resumed allowing ships to transit its straits toward the Black Sea after unexplained delays for some vessels amid heightened security risks in the area.","kImp":"보스포루스·다르다넬스 해협은 흑해 곡물·에너지 물류의 관문으로, 통항 지연·재개는 러시아-우크라이나 전쟁 리스크가 세계 물류에 미치는 영향을 보여준다.","eImp":"The Turkish Straits are the gateway for Black Sea grain and energy; transit disruptions show how the Russia-Ukraine war ripples through global logistics.","url":"https://gcaptain.com/turkey-resumes-black-sea-ship-transits-via-straits-after-delays/"},{"code":"GEO","title":"대만, 태풍 중 대만해협 선박 통제하려던 中 조치 강력 규탄","src":"gCaptain","date":"2026-08-09","kSum":"태풍 돌핀 기간 대만해협 진입 선박에 대해 중국이 교통 통제 조치를 시행하려 하자, 대만은 이를 '터무니없다'며 베이징이 국제수역 접근을 제한할 권리가 없다고 규탄했다.","eSum":"Taipei condemned as 'ridiculous' China's attempt to impose traffic-control measures on shipping entering the Taiwan Strait during Typhoon Dolphin, saying Beijing has no right to restrict access to international waters.","kImp":"대만해협 통제 시도는 중국의 해협 관할권 주장을 둘러싼 긴장을 재점화하며, 세계 최대 해상 무역로 중 하나의 항행 자유 리스크를 부각한다.","eImp":"The control attempt reignites tensions over China's strait-jurisdiction claims and freedom-of-navigation risks on one of the world's busiest trade routes.","url":"https://gcaptain.com/taipei-condemns-chinas-traffic-control-order-for-taiwan-strait-during-typhoon/"}]},{"code":"TW","type":"news","kTitle":"Section 18. 트레이드윈즈","eTitle":"Section 18. TradeWinds","items":[{"code":"TW","title":"Massive opportunity: Shipowners set fair as 'the whole world is asking for Chinese cars'","src":"TradeWinds","date":"2026-08-11","kSum":"트레이드윈즈(TradeWinds)는 '전 세계가 중국산 자동차를 원한다'며 중국 자동차 수출 급증으로 자동차운반선(PCTC) 선주들이 유리한 국면을 맞고 있다고 헤드라인으로 전했다.","eSum":"TradeWinds reports that surging Chinese car exports are putting car-carrier owners in a strong position, with 'the whole world asking for Chinese cars'.","kImp":"중국발 완성차 물동량이 PCTC 시장의 운임과 선복 수요를 끌어올리는 핵심 동력임을 보여준다.","eImp":"Signals that Chinese vehicle export volumes remain the key driver of PCTC freight rates and tonnage demand.","url":"https://www.tradewindsnews.com/containers/massive-opportunity-shipowners-set-fair-as-the-whole-world-is-asking-for-chinese-cars-/2-1-2027395"},{"code":"TW","title":"PanStar bets on Arctic future with vessel for Northern Sea Route","src":"TradeWinds","date":"2026-08-12","kSum":"한국 팬스타(PanStar)가 북극항로(Northern Sea Route) 운항을 겨냥한 선박에 투자하며 북극 해운의 미래에 베팅한다고 트레이드윈즈가 보도했다.","eSum":"TradeWinds reports South Korea's PanStar is betting on an Arctic future, lining up a vessel for the Northern Sea Route.","kImp":"북극항로 상업화 움직임이 아시아 선사로 확산되고 있음을 보여준다.","eImp":"Shows commercial interest in the Northern Sea Route is spreading to Asian operators.","url":"https://www.tradewindsnews.com/containers/panstar-bets-on-arctic-future-with-vessel-for-northern-sea-route/2-1-2027705"},{"code":"TW","title":"Red Sea return for container ships takes a significant step forward","src":"TradeWinds","date":"2026-08-11","kSum":"컨테이너선의 홍해(Red Sea) 복귀가 의미 있는 진전을 이뤘다고 트레이드윈즈가 헤드라인으로 전했다.","eSum":"TradeWinds headlines that container ships' return to the Red Sea has taken a significant step forward.","kImp":"홍해 항로 정상화는 아시아-유럽 컨테이너 운임과 항로 선택에 큰 영향을 미친다.","eImp":"A Red Sea normalisation would materially reshape Asia-Europe container routing and rates.","url":"https://www.tradewindsnews.com/containers/red-sea-return-for-container-ships-takes-a-significant-step-forward/2-1-2027444"},{"code":"TW","title":"Hanwha tables $1.2bn Austal bid to expand US shipbuilding footprint","src":"TradeWinds","date":"2026-08-11","kSum":"한화(Hanwha)가 미국 조선 입지 확대를 위해 호주 오스탈(Austal)에 12억 달러 인수를 제안했다고 트레이드윈즈가 보도했다.","eSum":"TradeWinds reports Hanwha has tabled a $1.2bn bid for Austal to expand its US shipbuilding footprint.","kImp":"한국 조선 자본의 미국·호주 방산 조선 진출 확대를 보여주는 대형 M&A다.","eImp":"A major M&A showing Korean shipbuilding capital expanding into US and Australian naval yards.","url":"https://www.tradewindsnews.com/shipyards/hanwha-tables-1-2bn-austal-bid-to-expand-us-shipbuilding-footprint/2-1-2027389"},{"code":"TW","title":"BW Group's Cadeler strikes $578m takeover after newbuilding splash","src":"TradeWinds","date":"2026-08-11","kSum":"BW그룹 계열 캐들러(Cadeler)가 신조 발주에 이어 5억 7,800만 달러 규모 인수에 나섰다고 트레이드윈즈가 전했다.","eSum":"TradeWinds reports BW Group's Cadeler has struck a $578m takeover following a newbuilding spree.","kImp":"해상풍력 설치선 부문의 통합이 가속되고 있음을 보여준다.","eImp":"Highlights accelerating consolidation in the offshore wind installation vessel sector.","url":"https://www.tradewindsnews.com/finance/bw-group-s-cadeler-strikes-578m-takeover-after-newbuilding-splash/2-1-2027593"},{"code":"TW","title":"Bulker player U-Ming triples quarterly profit","src":"TradeWinds","date":"2026-08-12","kSum":"대만 벌크선사 유밍(U-Ming)이 분기 순익을 3배로 늘렸다고 트레이드윈즈가 보도했다.","eSum":"TradeWinds reports Taiwanese bulker owner U-Ming has tripled its quarterly profit.","kImp":"벌크선 시황 강세가 아시아 선주 실적에 반영되고 있음을 보여준다.","eImp":"Reflects how firm dry bulk markets are feeding through to Asian owners' earnings.","url":"https://www.tradewindsnews.com/bulkers/bulker-player-u-ming-triples-quarterly-profit/2-1-2027611"},{"code":"TW","title":"Venture Global to produce around 900 LNG cargoes a year by 2028","src":"TradeWinds","date":"2026-08-12","kSum":"미국 벤처글로벌(Venture Global)이 2028년까지 연 약 900척 분량의 LNG 화물을 생산할 계획이라고 트레이드윈즈가 전했다.","eSum":"TradeWinds reports Venture Global plans to produce around 900 LNG cargoes a year by 2028.","kImp":"미국 LNG 수출 급증은 LNG선 신조·용선 수요를 견인한다.","eImp":"Surging US LNG output will drive LNG carrier newbuilding and chartering demand.","url":"https://www.tradewindsnews.com/gas/venture-global-to-produce-about-900-lng-cargoes-a-year-by-2028/2-1-2027601"},{"code":"TW","title":"Third fatal accident in 15 months puts CSBC shipyard under spotlight","src":"TradeWinds","date":"2026-08-12","kSum":"대만 CSBC 조선소에서 15개월 새 세 번째 사망사고가 발생해 안전 관리가 도마 위에 올랐다고 트레이드윈즈가 보도했다.","eSum":"TradeWinds reports a third fatal accident in 15 months has put Taiwan's CSBC shipyard under the safety spotlight.","kImp":"조선소 안전관리 실패가 반복되며 야드 감독 강화 압박이 커지고 있다.","eImp":"Repeated yard safety failures are intensifying pressure for stronger shipyard oversight.","url":"https://www.tradewindsnews.com/casualties/third-fatal-accident-in-15-months-puts-csbc-shipyard-under-spotlight/2-1-2027777"},{"code":"TW","title":"Seafarers feared killed in suspected Houthi missile attack","src":"TradeWinds","date":"2026-08-11","kSum":"후티(Houthi)의 미사일 공격으로 추정되는 사건에서 선원 사망이 우려된다고 트레이드윈즈가 전했다.","eSum":"TradeWinds reports seafarers are feared killed in a suspected Houthi missile attack.","kImp":"홍해·아덴만 선원 안전 위협이 재점화되며 항로 위험이 다시 부각된다.","eImp":"Renewed threat to seafarer safety in the Red Sea/Gulf of Aden underscores route risk.","url":"https://www.tradewindsnews.com/casualties/seafarers-feared-killed-in-suspected-houthi-missile-attack/2-1-2027533"},{"code":"TW","title":"Trump's energy experts forecast Hormuz disruption to last well into 2027","src":"TradeWinds","date":"2026-08-12","kSum":"트럼프 행정부 에너지 전문가들이 호르무즈(Hormuz) 해협의 혼란이 2027년까지 이어질 것으로 전망했다고 트레이드윈즈가 보도했다.","eSum":"TradeWinds reports Trump's energy experts forecast Hormuz disruption to last well into 2027.","kImp":"호르무즈 장기 불안은 유조선 운임과 우회 항로 프리미엄을 지지한다.","eImp":"Prolonged Hormuz instability supports tanker rates and rerouting premiums.","url":"https://www.tradewindsnews.com/tankers/trump-s-energy-experts-forecast-hormuz-disruption-to-last-well-into-2027/2-1-2027761"}]},{"code":"HOT","type":"news","kTitle":"Section 19. 호르무즈 위기","eTitle":"Section 19. Strait of Hormuz Crisis","items":[{"code":"HOT","title":"美 해군 헬기, 오만만서 파나마 선적 컨선에 헬파이어 발사…대이란 봉쇄 집행","src":"gCaptain","date":"2026-08-11","kSum":"미 중부사령부(CENTCOM)는 화요일 오만만에서 파나마 선적 컨테이너선 벨라노바호가 반복된 경고를 무시하고 대이란 봉쇄를 뚫으려 하자 헬파이어 미사일 2발을 발사해 선박을 무력화했다고 확인했다.","eSum":"US Central Command confirmed American forces fired two Hellfire missiles at the Panama-flagged containership Vela Nova in the Gulf of Oman, disabling it after it allegedly ignored warnings and tried to breach the US blockade of Iran.","kImp":"미군의 상선 직접 타격은 호르무즈·오만만 일대가 사실상 봉쇄·교전 구역으로 변했음을 보여주며, 전 세계 컨테이너·탱커 운항에 극심한 전쟁위험을 부과한다.","eImp":"A direct US strike on a merchant ship shows the Hormuz/Gulf of Oman has become a de facto blockade war zone, imposing severe war risk on global shipping.","url":"https://gcaptain.com/u-s-navy-helicopter-fires-on-panama-flagged-containership-in-gulf-of-oman-in-blockade-enforcement/"},{"code":"HOT","title":"트럼프 행정부 '걸프 원유 수송 하루 1500만 배럴로 회복'","src":"gCaptain","date":"2026-08-11","kSum":"크리스 라이트 미 에너지장관은 미군 작전과 파이프라인 증설로 이란과의 전쟁으로 교란됐던 수출이 회복되면서 페르시아만 원유 수송량이 하루 약 1500만 배럴로 늘었다고 밝혔다.","eSum":"US Energy Secretary Chris Wright said Persian Gulf oil flows have climbed to roughly 15 million barrels per day as US military operations and expanded pipeline capacity restore exports disrupted by the war with Iran.","kImp":"걸프 원유 수송 회복 주장은 유가·탱커 시장에 안도감을 주지만, 미군 작전에 의존한 수송 정상화는 지정학적 취약성이 여전함을 시사한다.","eImp":"Claimed recovery of Gulf oil flows reassures oil and tanker markets, but reliance on US military operations signals persistent geopolitical fragility.","url":"https://gcaptain.com/trump-administration-says-gulf-oil-flows-recover-to-15-million-barrels-a-day/"},{"code":"HOT","title":"홍해 바브엘만데브서 후티 공격에 선원 4명 사망…파키스탄 앞바다 컨선도 미사일 피격","src":"gCaptain","date":"2026-08-11","kSum":"예멘 교통부는 화요일 이란 지원 후티가 바브엘만데브 해협에서 소형 화물선을 공격해 선원 4명이 사망했다고 밝혔다. 동시에 파키스탄 앞바다에서 컨테이너선이 미사일 공격을 받았으며 미국의 소행으로 의심된다고 소식통이 전했다.","eSum":"Yemen's transport ministry said four crew were killed in an Iran-backed Houthi attack on a small cargo ship in the Bab el-Mandeb strait, while sources reported a missile strike on a container ship off Pakistan in a suspected US strike.","kImp":"홍해·아라비아해 양쪽에서 동시다발 공격은 지역 전쟁이 광범위한 해역으로 확산됐음을 보여주며, 선원 인명 피해와 전쟁위험 보험료 급등을 초래한다.","eImp":"Simultaneous attacks across the Red Sea and Arabian Sea show the conflict spreading widely, driving seafarer casualties and soaring war-risk premiums.","url":"https://gcaptain.com/four-crew-killed-in-red-sea-attack-while-missile-strike-reported-in-gulf/"},{"code":"HOT","title":"파키스탄 '美·이란 모종의 합의 임박'…카타르 '호르무즈 협상 진전'","src":"gCaptain","date":"2026-08-11","kSum":"파키스탄은 화요일 미국과 이란이 '모종의' 합의에 근접했다고 밝혔고, 공동 중재국 카타르는 호르무즈해협 관리에 관한 협상이 상당히 진전됐다고 전했다. 다만 역내 해상 공격이 계속되는 가운데 나온 발언이다.","eSum":"Pakistan said the US and Iran were close to 'some sort' of deal, and co-mediator Qatar said talks on managing the Strait of Hormuz were at an advanced stage, despite continuing attacks on regional shipping.","kImp":"중재국들의 낙관론은 호르무즈 재개통 기대를 키우지만, 지속되는 공격과 미국의 강경 조건이 겹쳐 합의 이행 불확실성이 크다.","eImp":"Mediators' optimism raises hopes for Hormuz reopening, but ongoing attacks and hard US conditions leave any deal highly uncertain.","url":"https://gcaptain.com/pakistan-says-us-and-iran-close-to-some-sort-of-deal-despite-attacks-on-shipping/"},{"code":"HOT","title":"UKMTO, 오만만서 컨테이너선-군사력 연루 사건 보고…파키스탄 앞바다 미사일 피격 추정","src":"gCaptain","date":"2026-08-11","kSum":"영국 해사무역기구(UKMTO)는 화요일 오만만에서 컨테이너선과 군사력이 연루된 사건 보고를 접수했다고 밝혔다. 해상보안 소식통은 해당 컨선이 파키스탄 앞바다에서 미사일에 피격된 것으로 보인다고 전했다.","eSum":"The UK Maritime Trade Operations said it received a report of an incident involving a container ship and military forces in the Gulf of Oman; security sources believe the ship was hit by a missile off Pakistan.","kImp":"UKMTO의 공식 경보는 오만만·호르무즈 접근로의 항행 위험을 재확인하며, 선사들의 회항·우회 및 보험료 인상 압력을 가중한다.","eImp":"The official UKMTO alert confirms navigation danger on the Gulf of Oman/Hormuz approaches, adding rerouting and premium-hike pressure on carriers.","url":"https://gcaptain.com/ukmto-reports-incident-involving-container-ship-and-military-forces-in-gulf-of-oman/"},{"code":"HOT","title":"트럼프, 이란에 강경 선회…'과거 공격 배상하라' 호르무즈 협상 먹구름","src":"gCaptain","date":"2026-08-11","kSum":"트럼프 미 대통령이 호르무즈해협 재개통 협상이 진행되는 가운데 이란에 대한 강경 태도를 굳혔다. 이란이 과거 공격에 대한 배상금을 지불해야 한다고 선언하며 협상 전망에 먹구름을 드리웠다.","eSum":"President Trump hardened his stance toward Iran as Hormuz reopening talks continue, declaring the Islamic Republic must pay reparations for past attacks, clouding prospects for a deal.","kImp":"미국의 배상 요구 등 강경 조건은 호르무즈 조기 재개통 기대를 약화시켜, 탱커 운임·유가의 고변동성과 공급 차질 장기화 우려를 키운다.","eImp":"US hardline conditions like reparations weaken hopes for an early Hormuz reopening, prolonging tanker-rate and oil-price volatility and supply disruption.","url":"https://gcaptain.com/trump-hardens-stance-on-iran-clouding-hopes-for-hormuz-deal/"},{"code":"HOT","title":"트럼프, 이란에 배상 요구…호르무즈 협상 타결 기대 후퇴","src":"gCaptain","date":"2026-08-10","kSum":"트럼프 대통령이 월요일 이란이 전쟁·공격·시위로 살해했다고 주장한 이들에 대한 배상을 요구했다. 이는 호르무즈해협 재개통 노력을 복잡하게 만들 가능성이 크다.","eSum":"President Trump on Monday demanded Iran pay compensation for people he said it had killed in wars, attacks and protests — a move likely to complicate efforts to reopen the Strait of Hormuz.","kImp":"세계 원유 해상 수송의 약 20~30%가 지나는 호르무즈 재개통 지연은 글로벌 에너지 시장과 탱커 운임에 지속적 하방·변동 압력을 가한다.","eImp":"Delayed reopening of Hormuz — through which ~20-30% of seaborne oil passes — keeps sustained pressure and volatility on global energy markets and tanker rates.","url":"https://gcaptain.com/trump-demands-compensation-from-iran-as-hormuz-deal-hopes-fade/"},{"code":"HOT","title":"이란 '호르무즈 재개통, 美 양보가 조건'…오만과 새 항로 협정 임박","src":"gCaptain","date":"2026-08-10","kSum":"이란은 오만과 호르무즈해협을 지나는 새로운 항로를 규정하는 협정 타결에 근접했다고 밝혔다. 다만 배상, 제재 해제, 군사 위협 중단 등 미국이 여러 조건을 충족해야 전략적 수로가 재개통될 것이라고 재차 강조했다.","eSum":"Iran said it was nearing a pact with Oman defining new shipping lanes through the Strait of Hormuz, but repeated that the US must meet conditions — compensation, sanctions relief and an end to military threats — before the waterway reopens.","kImp":"이란-오만 항로 협정은 부분 재개통 가능성을 시사하지만, 이란이 내건 정치적 전제조건들은 미국 입장과 충돌해 완전 정상화까지 상당한 시간이 걸릴 수 있다.","eImp":"An Iran-Oman lanes pact hints at partial reopening, but Iran's political preconditions clash with the US stance, delaying full normalization.","url":"https://gcaptain.com/iran-ties-hormuz-reopening-to-us-concessions-on-several-demands/"}]},{"code":"SYS","type":"news","kTitle":"Section 20. 해운 IT/시스템","eTitle":"Section 20. Maritime IT & Systems","items":[{"code":"SYS","title":"MG Ship takes logistics intelligence platform into Europe","src":"Splash247","date":"2026-08-11","kSum":"물류 인텔리전스 소프트웨어 업체 MG쉽(MG Ship)이 자사 플랫폼을 유럽 시장으로 확장한다. 해상·물류 데이터를 통합 분석하는 SaaS형 인텔리전스 도구의 지역 확대 사례다.","eSum":"Logistics intelligence software firm MG Ship is expanding its platform into Europe. The move is a regional rollout of a SaaS-style intelligence tool that integrates and analyses maritime and logistics data.","kImp":"물류 인텔리전스 SaaS의 확장은 데이터 기반 운영 도구의 시장 성장을 방증한다.","eImp":"A logistics-intelligence SaaS expansion evidences growth in data-driven operations tools.","url":"https://splash247.com/mg-ship-takes-logistics-intelligence-platform-into-europe/"},{"code":"SYS","title":"India debuts E-Samudra maritime governance platform","src":"Splash247","date":"2026-08-10","kSum":"인도가 선원, 해운사, 항만 등 해양 이해관계자를 위한 서비스를 하나로 통합한 디지털 플랫폼 이-사무드라(E-Samudra)를 출범했다. 정부 주도의 해운 행정·서비스 디지털화 시스템이다.","eSum":"India has launched E-Samudra, a new digital platform bringing services for seafarers, shipping companies, ports and other maritime stakeholders into one place. It is a government-led system digitalising maritime administration and services.","kImp":"국가 단위 해운 행정 플랫폼은 규제·서류 처리의 디지털 표준화를 가속한다.","eImp":"A national maritime governance platform accelerates digital standardisation of admin and paperwork.","url":"https://splash247.com/india-debuts-maritime-governance-platform/"},{"code":"SYS","title":"Evergreen plugs into WaveBL electronic bill of lading network","src":"Splash247","date":"2026-08-11","kSum":"컨테이너 선사 에버그린(Evergreen)이 블록체인 기반 전자선하증권(eBL) 플랫폼 웨이브BL(WaveBL) 네트워크에 연결했다. 종이 선하증권을 대체하는 전자 문서 시스템 채택이 주요 선사로 확산되고 있다.","eSum":"Container line Evergreen has connected to the WaveBL network, a blockchain-based electronic bill of lading (eBL) platform. Adoption of electronic documentation systems replacing paper bills of lading continues to spread among major carriers.","kImp":"주요 선사의 eBL 채택 확대는 무역 문서 디지털화의 임계점을 앞당긴다.","eImp":"Wider eBL adoption by major carriers brings trade-document digitalisation closer to critical mass.","url":"https://splash247.com/evergreen-plugs-into-wavebl-network/"},{"code":"SYS","title":"PIL expands process intelligence push with Celonis and WNS","src":"Splash247","date":"2026-08-06","kSum":"퍼시픽인터내셔널라인스(PIL)가 셀로니스(Celonis), WNS와 손잡고 글로벌 프로세스 인텔리전스 센터를 확장한다. 업무 프로세스 데이터를 분석해 운영 효율을 높이는 소프트웨어 기반 이니셔티브다.","eSum":"Pacific International Lines (PIL) has partnered Celonis and WNS to expand its global Process Intelligence Centre of Excellence. The software-driven initiative mines business-process data to raise operational efficiency.","kImp":"프로세스 마이닝 도입은 선사 백오피스 자동화·효율화의 실무 방향을 보여준다.","eImp":"Process-mining adoption points the way for carrier back-office automation and efficiency.","url":"https://splash247.com/pil-expands-process-intelligence-push-with-celonis-and-wns/"},{"code":"SYS","title":"Klaipeda Container Terminal to implement Portchain berth planning software","src":"Smart Maritime Network","date":"2026-08-06","kSum":"클라이페다 컨테이너 터미널(KCT)이 디지털화 프로그램의 일환으로 포트체인(Portchain)의 퀘이(Quay) 선석 계획 소프트웨어를 도입한다. 실시간 일정 갱신으로 선석 계획과 선박 스케줄을 정렬하는 항만 IT 시스템이다.","eSum":"Klaipeda Container Terminal (KCT) is to implement Portchain's Quay berth planning software as part of its digitalisation programme. The port IT system aligns berth plans with vessel schedules through real-time updates.","kImp":"항만 선석 계획 소프트웨어 도입은 터미널 생산성 디지털화의 확산을 보여준다.","eImp":"Berth-planning software uptake shows spreading digitalisation of terminal productivity.","url":"https://smartmaritimenetwork.com/2026/08/06/klaipeda-container-terminal-to-implement-berth-planning-software/"},{"code":"SYS","title":"LeBeouf rolls out OpenTug's BargeOS platform across barge operations","src":"Splash247","date":"2026-08-05","kSum":"미국 내륙 탱크바지 운영사 르뵈프브라더스토잉(LeBeouf Bros Towing)이 오픈터그(OpenTug)의 BargeOS 플랫폼을 전사적으로 도입 완료했다. 상업·운영 업무를 아우르는 SaaS형 바지 운영 관리 시스템이다.","eSum":"US inland tank barge operator LeBeouf Bros Towing has completed an enterprise-wide rollout of OpenTug's BargeOS platform across its commercial and operational functions. BargeOS is a SaaS system for managing barge operations end to end.","kImp":"내륙 운송으로의 SaaS 확산은 해운 IT 시장 저변 확대를 보여준다.","eImp":"SaaS reaching inland transport shows the broadening base of the maritime IT market.","url":"https://splash247.com/lebeouf-puts-opentug-platform-across-barge-operations/"},{"code":"SYS","title":"PTC pilots bigyellowfish digital health platform across selected fleets","src":"Splash247","date":"2026-08-05","kSum":"필리핀 선원관리사 PTC와 젭슨PTC마리타임이 선주 대상으로 빅옐로피시(bigyellowfish)의 디지털 헬스 플랫폼 시범 운영을 준비 중이다. 선원 정신·신체 건강을 관리하는 앱 기반 시스템이다.","eSum":"Philippine Transmarine Carriers and Jebsen PTC Maritime are preparing to pilot bigyellowfish's digital health platform with selected shipping principals. It is an app-based system for managing seafarer mental and physical wellbeing.","kImp":"선원 복지 관리의 앱 기반 디지털화가 선원관리 업계로 확산되고 있다.","eImp":"App-based digitalisation of crew welfare is spreading across ship management.","url":"https://splash247.com/ptc-pilots-bigyellowfish-health-platform-across-selected-fleets/"},{"code":"SYS","title":"Flag states pressed to ditch paper training record books","src":"Splash247","date":"2026-08-06","kSum":"해상 교육기관 마린팔스(MarinePALS)가 아직 종이 훈련기록부에 의존하는 기국 당국에 전자 훈련기록 승인 경로 마련을 촉구했다. 선원 교육기록의 디지털화·전자 시스템 전환을 요구하는 움직임이다.","eSum":"Maritime training provider MarinePALS has called on flag administrations still relying on paper training record books to establish approval routes for electronic records. The push seeks a shift to digital, app-based training documentation.","kImp":"교육기록의 전자화 요구는 선원 서류 시스템의 디지털 전환 압력을 반영한다.","eImp":"Calls to digitise training records reflect pressure to modernise crew documentation systems.","url":"https://splash247.com/flag-states-pressed-to-ditch-paper-training-books/"},{"code":"SYS","title":"Nippon Paint Marine logs more than 2,500 coated vessels on RightShip","src":"Splash247","date":"2026-08-06","kSum":"닛폰페인트마린(Nippon Paint Marine)이 자사 선체 코팅 시스템을 사용하는 2,557척의 선박을 라이트십(RightShip) 플랫폼에 등록했다고 밝혔다. 성능·환경 데이터를 축적하는 디지털 선박평가 플랫폼 활용 사례다.","eSum":"Nippon Paint Marine says 2,557 vessels using its hull coating systems have now been registered on RightShip's platform, building a growing performance dataset. It highlights use of a digital vetting/rating platform to aggregate vessel data.","kImp":"공급사가 디지털 평가 플랫폼에 성능 데이터를 축적하며 데이터 생태계가 확장된다.","eImp":"Suppliers feeding performance data into vetting platforms expands the maritime data ecosystem.","url":"https://splash247.com/nippon-paint-marine-logs-more-than-2500-coated-vessels-on-rightship/"}]},{"code":"SMGR","type":"news","kTitle":"Section 21. 선박관리사","eTitle":"Section 21. Ship Management","items":[{"code":"SMGR","title":"NAPA launches digital checklist system","src":"Smart Maritime Network","date":"2026-08-11","kSum":"핀란드 해사 소프트웨어사 나파(NAPA)가 선상 점검을 디지털화하는 전자 체크리스트 시스템을 출시했다. 종이 기반 점검을 대체해 선박관리사의 안전·규정 준수 업무 효율을 높인다.","eSum":"Finnish maritime software firm NAPA has launched a digital checklist system to replace paper-based shipboard inspections, streamlining safety and compliance work for ship managers.","kImp":"선박관리사의 안전관리체계(SMS) 점검을 디지털화해 감사 대응과 규정 준수 부담을 줄여준다.","eImp":"Digitises SMS inspections for ship managers, easing audit readiness and compliance workload.","url":"https://smartmaritimenetwork.com/2026/08/11/napa-launches-digital-checklist-system/"},{"code":"SMGR","title":"Anschütz updates bridge software with new navigation functions","src":"Smart Maritime Network","date":"2026-08-11","kSum":"독일 항해장비사 안쉬츠(Anschütz)가 선교(bridge) 소프트웨어를 업데이트해 새로운 항해 기능을 추가했다. 관리 선대의 항해 안전과 운항 효율 향상을 지원한다.","eSum":"German navigation specialist Anschütz has updated its bridge software with new navigation functions, supporting safer, more efficient voyages across managed fleets.","kImp":"선교 소프트웨어 고도화는 선박관리사가 운용하는 선대의 항해 안전 수준을 끌어올린다.","eImp":"Enhanced bridge software raises navigational safety standards across managed fleets.","url":"https://smartmaritimenetwork.com/2026/08/11/anschutz-updates-bridge-software-with-new-navigation-functions/"},{"code":"SMGR","title":"Marlink to acquire UK defence comms company GRC","src":"Smart Maritime Network","date":"2026-08-11","kSum":"선박 통신 대기업 마링크(Marlink)가 영국 방산 통신기업 GRC를 인수하기로 했다. 관리 선대에 제공하는 위성·사이버 연결 역량을 확대한다.","eSum":"Maritime connectivity giant Marlink has agreed to acquire UK defence communications company GRC, expanding the satellite and cyber connectivity it provides to managed fleets.","kImp":"선대 연결성·사이버보안 서비스 통합이 가속되며 선박관리사의 디지털 인프라 선택지가 넓어진다.","eImp":"Accelerating consolidation in fleet connectivity and cyber services broadens ship managers' digital infrastructure options.","url":"https://smartmaritimenetwork.com/2026/08/11/marlink-to-acquire-uk-defence-comms-company-grc/"},{"code":"SMGR","title":"PTC and bigyellowfish expand access to seafarer health platform","src":"Smart Maritime Network","date":"2026-08-05","kSum":"필리핀 선원공급사 PTC와 헬스테크 빅옐로우피시(bigyellowfish)가 선원 건강·웰빙 플랫폼 이용을 확대한다. 선원의 정신건강과 복지 지원을 강화한다.","eSum":"Philippine crewing group PTC and health-tech firm bigyellowfish are expanding access to their seafarer health and wellbeing platform, strengthening crew mental-health support.","kImp":"선원 복지·정신건강 투자는 선박관리사의 인력 유지와 크루 웰빙 경쟁력을 높인다.","eImp":"Investment in crew welfare and mental health boosts ship managers' retention and wellbeing credentials.","url":"https://smartmaritimenetwork.com/2026/08/05/ptc-and-bigyellowfish-expand-access-to-seafarer-health-platform/"},{"code":"SMGR","title":"PIL expands Intelligence Centre","src":"Smart Maritime Network","date":"2026-08-06","kSum":"싱가포르 선사 PIL(Pacific International Lines)이 선대 운영을 실시간 모니터링하는 인텔리전스 센터(Intelligence Centre)를 확장했다. 선대 안전·효율 관리 역량을 강화한다.","eSum":"Singapore's PIL (Pacific International Lines) has expanded its Intelligence Centre for real-time fleet monitoring, strengthening its fleet safety and efficiency management.","kImp":"실시간 선대관제센터 확장은 선박운영관리의 디지털 전환 흐름을 보여준다.","eImp":"The expanded fleet operations centre reflects the digital shift in vessel operations management.","url":"https://smartmaritimenetwork.com/2026/08/06/pil-expands-intelligence-centre/"},{"code":"SMGR","title":"Klaipeda Container Terminal to implement berth planning software","src":"Smart Maritime Network","date":"2026-08-06","kSum":"리투아니아 클라이페다 컨테이너터미널(Klaipeda Container Terminal)이 선석 계획 소프트웨어를 도입한다. 선박 접안·하역 계획의 효율을 높인다.","eSum":"Lithuania's Klaipeda Container Terminal will implement berth planning software to improve vessel berthing and cargo-handling efficiency.","kImp":"터미널 디지털화는 관리 선대의 재항시간 단축과 정시성 개선에 기여한다.","eImp":"Terminal digitisation helps cut port stays and improve schedule reliability for managed fleets.","url":"https://smartmaritimenetwork.com/2026/08/06/klaipeda-container-terminal-to-implement-berth-planning-software/"},{"code":"SMGR","title":"MG Ship launches shipment visibility platform in Europe","src":"Smart Maritime Network","date":"2026-08-11","kSum":"MG Ship가 유럽에서 화물 가시성(shipment visibility) 플랫폼을 출시했다. 화주와 선사에 실시간 화물 추적을 제공한다.","eSum":"MG Ship has launched a shipment visibility platform in Europe, offering shippers and operators real-time cargo tracking.","kImp":"화물 가시성 플랫폼 확산은 선사·운영관리의 데이터 기반 의사결정을 뒷받침한다.","eImp":"Wider cargo-visibility tools support data-driven decision-making in vessel operations.","url":"https://smartmaritimenetwork.com/2026/08/11/mg-ship-launches-shipment-visibility-platform-in-europe/"},{"code":"SMGR","title":"Evergreen to expand eBL reach through WaveBL integration","src":"Smart Maritime Network","date":"2026-08-11","kSum":"대만 에버그린(Evergreen)이 웨이브BL(WaveBL) 연동을 통해 전자선하증권(eBL) 활용을 확대한다. 서류 처리의 디지털화·투명성을 높인다.","eSum":"Taiwan's Evergreen will expand use of electronic bills of lading (eBL) through WaveBL integration, boosting the digitisation and transparency of documentation.","kImp":"eBL 확산은 해운 서류업무의 디지털 전환과 처리 속도 향상을 보여준다.","eImp":"Growing eBL adoption illustrates the digital transformation of shipping documentation.","url":"https://smartmaritimenetwork.com/2026/08/11/evergreen-to-expand-ebl-reach-through-wavebl-integration/"},{"code":"SMGR","title":"Incheon fully automated terminal to deploy CyberLogitec software","src":"Smart Maritime Network","date":"2026-08-11","kSum":"인천의 완전 자동화 터미널이 사이버로지텍(CyberLogitec) 소프트웨어를 도입한다. 자동화 항만 운영 시스템을 강화한다.","eSum":"A fully automated terminal in Incheon will deploy CyberLogitec software to strengthen its automated port operations.","kImp":"한국 자동화 터미널 확산은 선대 기항 효율과 항만 생산성 향상에 기여한다.","eImp":"Growth of Korean automated terminals boosts port productivity and vessel turnaround.","url":"https://smartmaritimenetwork.com/2026/08/11/incheon-fully-automated-terminal-to-deploy-cyberlogitec-software/"}]}]};
